pack.loaded = true
local quests = pack.locales.enUS

quests[11208] = { id = 11208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery for Drazzit", description = "Drazzit will expect to hear something from me soon, but I don't think the site is secure enough for me to leave. If you have time, would you be willing to take some of the salvaged cargo down to him at Mudsprocket?\n\nIf you haven't been there yet, it's a small settlement to the southwest of here, beyond the Stonemaul Ruins. You can take the road there from Tabetha's Farm, too. When you get to Mudsprocket, the guy you're looking for is Drazzit Dripvalve.", progress = "Yes?", completion = "<Drazzit accepts the cargo from you.>\n\nI'm so hungry, I could eat a dragon! Thank goodness Moxie finally got some of that cargo down here. We've been reduced to playing dice against the ogre for whatever he's managed to kill on his hunting trips!", objectives = "Take the Zeppelin Cargo to Drazzit Dripvalve at Mudsprocket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11209] = { id = 11209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "at's Bargain", description = "So you found a copy of Dastardly Denizens of the Deep, did you? Well, I can tell you from experience, it's all true. I've even seen a few of 'em with my own eyes.\n\nBut you want to know about Tethyr.  I said I'd make you a deal, so here's what I want you to do. I'm working on a new line of baits, but I haven't tested this one yet.\n\nJust take this paste -- yeah, it smells a little foul -- smear it on yourself, and swim over to that wrecked ship to the southwest. If you survive, let me know how it works!", progress = "Remember, the deal is \"don't come back until something bites you.\"", completion = "Not bad at all, but you know, I think I'd get a bath in as soon as possible, if I was you.\n\nNow, about your sea monster...\n\nHelp yourself to a brew or two in the meantime.", objectives = "Nat Pagle at Nat's Landing wants you to test his new fish bait.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11210] = { id = 11210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "h, It's Real", description = "Yes, Tethyr is certainly real, and he lives in the waters off Theramore.\n\nHas a thing for bright lights. He's the reason they shut down the lighthouse in the first place, you know...\n\nAnd if you light it up again, he'll come right back. But no one in their right mind would do that.\n\nSo that must be your plan! It's been good sharing a drink with you, but don't blame ol' Nat if Tethyr REALLY turns you into fish bait. If you're going to do this, make sure you consult Major Mills at the Theramore docks.", completion = "<You recount your experiences with Nat Pagle, carefully omitting the portion about the 'bait test.'>\n\nWell, it sounds like we've got our work cut out for us. I'll make the preparations.", objectives = "Speak with Major Mills at the docks in Theramore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11211] = { id = 11211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help for Mudsprocket", description = "When that goblin... what's her name... Boxie, Foxy... Moxie, that's it! Anyway, when she came through here on her way to the zeppelin wreck, she said the town of Mudsprocket was having some problems.\n\nThat crashed zeppelin was bringing them fresh supplies. If you follow the road south from here, past the Stonemaul Ruins, you'll eventually come to Mudsprocket.\n\nWhy don't you check in with Drazzit Dripvalve down there and see if there's anything you can do to help?", completion = "It's good of Tabetha to send you down here. I'd prevail upon her for some food until the wreckage from the zeppelin is taken care of, but I know she's got none to spare at the moment. If you're feeling adventurous, I've posted a bounty for the death of a particularly nasty raptor.", objectives = "Speak with Drazzit Dripvalve at Mudsprocket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11212] = { id = 11212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tabetha's Farm", description = "Deep in the heart of the swamp lives an old woman named Tabetha. We've never really known much about her, save that she's a good deal older than she appears. She's helped us from time to time and helped keep the peace here between the Horde and our forces.\n\nShe used to keep in regular contact, but we haven't received one lately.\n\nCould you check in with her when you have time? Just follow the road beyond North Point Tower, where it turns south and into the Quagmire. You can see her farm from the road.", completion = "It's good of Theramore to send someone. Your guard friend's suspicions were correct. We've got some new neighbors, and they aren't the kind you'd bring a casserole.", objectives = "Speak with Tabetha at her farm in the Quagmire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11213] = { id = 11213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Check Up on Tabetha", description = "A human woman named Tabetha lives on a small farm near the middle of the marsh. Ordinarily, I wouldn't associate with a human, but her help has proven useful at times.\n\nUnfortunately, she's been out of touch for quite some time now and I'm looking for someone to travel down to her farm to see if everything's all right.\n\nIf you follow the road south out of the village, then into the swamp's interior, you'll find her farm near the middle of the Quagmire.", completion = "It's fortunate Nazeer thought to send someone. We've got some new neighbors and they've been nothing but pests since they set up camp.", objectives = "Speak to Tabetha at her farm in the Quagmire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11214] = { id = 11214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ission to Mudsprocket", description = "The Steamwheedle Cartel has recently established a new outpost in the southern part of Dustwallow Marsh. It's called Mudsprocket, if I recall, and it's located on the main road south out of Tabetha's Farm and the Stonemaul Ruins.\n\nThis is an excellent opportunity for us to establish new trade contacts and Lady Jaina wants me to send a representative down there to establish contact. Would you be willing to go?", completion = "So Theramore is interested in doing business? Well, that's not an offer I'd turn down. Supplies are pretty scarce here right now, so we need all the business contacts we can get!", objectives = "Speak with Drazzit Dripvalve at Mudsprocket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11215] = { id = 11215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help Mudsprocket", description = "The Steamwheedle Cartel's new outpost in the southern part of the marsh isn't faring so well. The zeppelin carrying supplies to Mudsprocket crashed, leaving them without vital tools, food, and medical supplies.\n\nFollow the road down south and into the marsh's interior. You'll pass by Tabetha's Farm and the Stonemaul Ruins before the road brings you to Mudsprocket. Offer any help you can provide to the town's leadership.", completion = "I won't turn down any help! We're in the process of setting up here and trying to make the most of what we've got, until those supplies from the zeppelin arrive.", objectives = "Speak with Drazzit Dripvalve at Mudsprocket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11216] = { id = 11216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archmage Alturus", description = "I was sent here by my mentor to look for assistance, but unfortunately I'm not allowed outside of Lower City and the individuals that frequent this establishment tend to be less than helpful.\n\nYou do seem different, more like the adventurous type.  If you're interested in aiding our cause, speak to Archmage Alturus outside of Medivh's old dwelling, Karazhan.\n\nIn the meantime, I'm going to see about gaining access to the rest of the city.  One of our old associates is rumored to be here.", completion = "I thank you for taking the time to come to our aid.  We've important work ahead of us.", objectives = "Speak to Archmage Alturus outside of Karazhan in Deadwind Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11217] = { id = 11217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "atch a Dragon by the Tail", description = "With the zeppelin crash delaying supplies, we've run out of medicines and bandages.\n\nWe're making use of what we can, but between all the insects, the injuries, and the enemies we're encountering here, I can barely keep up! I've found one herb that seems to help heal wounds and dull pain, but it, too, is in short supply.\n\nIt's called wyrmtail, and it's abundant in the Dragonmurk and Wyrmbog areas east of town. The plants themselves are made of coiled stalks, and seem to pulsate when you look at them.", progress = "Did you find any of the wyrmtail?", completion = "Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash.", objectives = "Gizzix Grimegurgle at Mudsprocket wants you to bring him 8 Wyrmtail stalks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11218] = { id = 11218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danger! Explosives!", description = "{name}, the captain's tasked me with a mission. I'd like you to help.\n\nA bunch of my fellow Explorers' League people went nuts digging up stuff in the Whisper Gulch just to the north. They're attacking anyone trying to get in!\n\nThe captain is only concerned with the ore for the keep. Lucky for us, I have just the thing to do the trick.\n\nGet in there, blow up the ore, and bring it back along with any gems you find. Running this place isn't cheap you know!\n\nI gotta warn you though, that ore is strange!", progress = "Construction on this place seems to be a never-ending task. I just hope that you're able to get us what we need to continue.", completion = "The ore gave you a strange feeling? Maybe we won't use that stuff after all.\n\n<Steelring looks at the stuff and takes a step back, changing the subject.>\n\nThose gems look really nice! I wonder what I can get for them? Of course, there are always repairs, and new stuff to be made.\n\nYou know, I've really found working with you to be profitable. Take this... it's the least that I can do!", objectives = "Use Steelring's Foolproof Dynamite to collect 6 Whisper Gulch Ore Fragments and 18 Whisper Gulch Gems. Then return them to Sapper Steelring at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11219] = { id = 11219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Fires!", description = "The Horde's children need you, {name}.  The Headless Horseman, once a human paladin and now an insane fiend, has set fire to our village!  You must put out those fires!\n\nGrab a bucket and throw it onto the blaze, or toss it to an ally who is closer to the flames.  Extinguish all the fires and thwart the Headless Horseman!", progress = "The Horde's children need you! Do not abandon them!", completion = "The fires are out! You and your fire brigade were victorious! Hah!\n\nThe Headless Horseman's attack has failed, but until he and his head are destroyed together, He will return.\n\nUntil then, however, let's take comfort in the safety you brought our children. I am honored to have watched your brave work today.", objectives = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11220] = { id = 11220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Headless Horseman", description = "Until the head of the Headless Horseman is destroyed, his rampage will not end.\n\nThe Horseman rests within the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades.  Go to his pumpkin shrine and speak these words:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nThis will rouse the fiend.  Destroy the head of the Horseman and he will plague us no longer.", sourceObjective = "Find the Headless Horseman's Pumpkin Shrine.Until the head of the Headless Horseman is destroyed, his rampage will not end.\n\nThe Horseman rests within the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades. Go to his pumpkin shrine and speak these words:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nThis will rouse the fiend. Destroy the head of the Horseman and he will plague us no longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[11221] = { id = 11221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reports from the Field", description = "Our mission in Northrend is to destroy Arthas.  The Alliance are but an obstacle that we'll crush wherever we find them.\n\nWe've managed to destroy their easternmost fleet; but the survivors have barricaded themselves on the Derelict Strand, south of here.\n\nOur forces should've overwhelmed their make-shift defenses long ago, but we underestimated their will to live.  Seek my officers in the field, Dark Ranger Lyana and Deathstalker Razael and get them to report on the situation.", progress = "Are you back with your report, {name}?", completion = "Cannons are holding us back?  I'll show them cannons.", objectives = "Speak to Dark Ranger Lyana and Deathstalker Razael in the battlefield at the Bleeding Vale south of Vengeance Landing. Return to High Executor Anselm when you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11222] = { id = 11222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "roof of Treachery", description = "Although Onyxia has been exposed and removed from the court, the Defias who carried out her plan must be punished. Carry word to King Varian Wrynn in Stormwind castle that the Defias are the ones who carried out his kidnapping. I have little doubt that the king will mete out swift and terrible justice to those involved.\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, {name}.", sourceObjective = "Speak to King Varian Wrynn in Stormwind Keep.", sourceObjectiveStatus = "unverified-source-field" }
quests[11223] = { id = 11223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "eturn to Jaina", description = "I must make plans to destroy the remnants of the Defias. Please convey my thanks to Lady Jaina, back in Theramore. She has ever been a loyal friend and steadfast ally.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.", sourceObjective = "Speak to Lady Jaina Proudmoore in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[11224] = { id = 11224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send Them Packing", description = "I've heard rumors of bad happenings in the Whisper Gulch to the north. Most of the Explorers' League went down into that place, and some say they went mad with what they discovered.\n\nThat doesn't change the fact that they took most of our mules and equipment with them, though. I won't lose those mules!\n\nIf you find yourself in there, and happen across any of my mules, just get up close on them and threaten them with a raised hand. They'll spook and come home for sure.", progress = "This is quite a blow to our efforts. I don't even want to know what they discovered down there.\n\nIt's enough to keep me awake at night just trying to imagine what it could be.", completion = "I'm indebted to you, {class}. At least with most of the mules and equipment recovered, we can hope to rebuild our numbers soon.\n\nPlease, take this.", objectives = "Explorer Abigail has asked you to /raise your hand at 10 Abandoned Pack Mules and then return to her at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11225] = { id = 11225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hermit of Witch Hill", description = "The marsh seems to have a strange effect on humans. Some grow mad simply by living here.\n\nAnyone who has ever settled at Swamplight Manor has gone mad in a spectacular way. The latest owner, one \"Swamp Eye\" Jarl, is already showing signs.\n\nI don't completely understand what's happening there, you'd have my thanks for looking into it.\n\nThe manor is at the eastern edge of the swamp. Trek east across Bluefen and past North Point Tower. The manor is in a haunted patch of land called Witch Hill.", completion = "Have you come here to spy on me? No?\n\nPerhaps you have an appreciation for fine cuisine, then? Good, you can help!", objectives = "Speak with \"Swamp Eye\" Jarl at Swamplight Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11226] = { id = 11226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upper Deck Promo - Spectral Tiger Mount" }
quests[11227] = { id = 11227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Eat Crow", description = "The high executor wants me to use my dogs to sniff out enemy scouts, but I can tell you right now these plaguehounds aren't going anywhere until they're properly fed.\n\nIf our military doesn't understand that these beasts are picky enough to not eat the rubbish they've given me, then they can't expect them to be of any use in the field.\n\nYou seem to have some time on your hands, why don't you take one of these dogs out hunting for crows out west?  Their meat isn't very tasty to us, but my boys love it!", completion = "Did you hunt down some crows, boy?  Good boy, good boy!\n\nAh, these hounds remind me of my days raising purebreds in Tirisfal... those were good times!", objectives = "Pontius, the kennel keeper at Vengeance Landing, wants you to use the Plaguehound Cage to summon a Hungry Plaguehound and feed it Crow Meat from Fjord Crows west of Vengeance Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11228] = { id = 11228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hell Has Frozen Over...", description = "Fordragon's got another thing coming if he thinks the group of green-gilled scrubs he sent to defend this port can hold out much longer.\n\n<Macalroy raises an eyebrow as he examines your equipment.>\n\nYou, however, might fare a bit better.\n\nThe importance of holding this port cannot be stated enough; and with those monsters flying overhead, the situation around here has gone from bad to worse.\n\nReport to Vice Admiral Keller just northwest of here and let him know that you're all out of bubble gum.", completion = "The dwarf speaks the truth. We can't afford to lose this port. It's one of two safe harbors that the Alliance has on this chunk of frozen hell - the other being a few hundred miles west of here on the coast of the Borean Tundra.", objectives = "Speak with Vice Admiral Keller at Valgarde Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11229] = { id = 11229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Windrunner Fleet", description = "We have the Windrunner, the Queen's Reprisal and the Oblivion stationed just east of the Derelict Strand.  Send orders to the fleet's commander, Captain Harker, that they're to destroy the Alliance's cannons.\n\nSpeak to our bat handler, Camille, and ask for passage to the fleet's location.  Be quick, {name}, every minute we spend fighting the Alliance is a minute we could've spent fighting Arthas.", completion = "I hope you're ready to fight, {name}.  The Queen's fleet needs you!", objectives = "Speak to Bat Handler Camille at Vengeance Landing and obtain passage to the Windrunner. Report to Captain Harker aboard the ship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11230] = { id = 11230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambushed!", description = "This should have been a walk in the park.  Their forces are hungry, injured and ill equipped.  Yet somehow, we walked right into their trap.\n\nWe approached these reefs from the south to gain cover and were immediately boarded by the Alliance dogs.\n\nI'm sorry to say, if you want our cannons to fire at anything, you're going to have to help us take our ships back.", progress = "What are you waiting for?  Kill the Alliance scum already!", completion = "Nice work paring those mongrels down to size.  My men will be able to clean up the rest.", objectives = "Captain Harker aboard the Windrunner wants you to kill 15 North Fleet Marines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11231] = { id = 11231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Keys and Cages", description = "The captain may not care, but from the little we know, the vrykul are conducting heinous rites in some sort of 'awakening' ritual up north in Gjalerbron.\n\nThey're using living sacrifices to fuel their unholy rituals!\n\n{class}, you must put a stop to this! It matters not who or what is in those cages, they must be freed. I'd bet that the vrykul hold the keys.\n\nThe Light knows the last thing we need is more of those strange vrykul walking about, or worse yet, them wakening something even more evil!", completion = "Bless you child! With your help, the Light shines even in the darkest of places.\n\nPlease, take this as just compensation for your good deeds. I shall see to the salvation of those you freed; at least, those truly within the Light, and the Alliance, who returned here to the keep.", objectives = "Father Levariol has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to him at Westguard Keep when you manage to do so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11232] = { id = 11232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guide Our Sights", description = "We should be able to kill our way back to our guns.  Unfortunately, visibility is less than desirable so you will have to mark our targets from the ground.\n\nTake these smoke flares with you and use them to mark the locations of the cannons along the northern wall in the Derelict Strand, west of here, where the Alliance are holding out.\n\nLet Lyana know as soon as the way is clear for the ground troops.  We can take care of ourselves over here.", progress = "The cannons, {name}.  Is someone going to take care of them?", completion = "Excellent.  I will signal our ground troops to make their move.", objectives = "Use the Smoke Flares at the location of the Alliance Cannons on the northern wall of the Derelict Strand. Report to Dark Ranger Lyana at the Bleeding Vale after you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11233] = { id = 11233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landing the Killing Blow", description = "You've proven yourself in the field of battle, {name}.  You might very well have changed the tides in our favor.\n\nI've an important assignment for you now.  I'm not sure how much longer the weakness we've exposed is going to last, so we must use the element of surprise to our advantage.\n\nI want you to use the confusion created by our attack and go behind enemy lines to assassinate their leaders.  In order of rank, they are: Captain Olster, Lieutenant Celeyne and Sergeant Lorric.  Good luck, {class}.", completion = "This marks undisputable victory for our forces.  Anselm will be most glad to hear about this.", objectives = "Dark Ranger Lyana south of the Vengeance Landing wants you to kill Captain Olster, Lieutenant Celeyne, and Sergeant Lorric at the Derelict Strand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11234] = { id = 11234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Anselm", description = "Let's send word back to old Anselm then.  Victory has come later than expected, but better late than never.  Tell him it will take our forces a few hours at most to finish off the stragglers here.\n\nGlory to the Banshee Queen!", completion = "It was about time.  The Alliance has been a thorn in our side for a long time now.\n\nThere's no time to celebrate, however.  Look to the west, it appears we have visitors.", objectives = "Report back to High Executor Anselm at Vengeance Landing in Howling Fjord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11235] = { id = 11235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing With Gjalerbron", description = "And now we have a different problem. My scouts that have lived to return have informed me that the vrykul are up to no good at their main fortress to the north.\n\nThey call the place Gjalerbron, though you'd pronounce the 'Gj' as if it were an 'Sh'. Odd creatures.\n\nBut that's not important; what is, is that you get up there and put an end to the lives of as many of those creatures as you can while trying to figure out what they're up to.\n\nI know that I can count on you, {name}.", completion = "Good work, {name}, and good riddance.\n\nBut, what you say about that place troubles me still, and I think our culling is not quite at an end!", objectives = "Captain Adams has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11236] = { id = 11236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necro Overlord Mezhen", description = "The Scourge are at Gjalerbron and they have necromancers with them! They must be working to bring the vrykul into Arthas' fold.\n\nI want the leader of these necrolords eliminated!\n\nDo whatever it takes, {name}, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized.\n\nI will not see the vrykul successfully allied with the Scourge!\n\nLook for Mezhen on the platform in the rear right section of Gjalerbron.", completion = "<The captain breathes a sigh of relief.>\n\nWell, that should take some of the pressure off of us.\n\n{name}, time and again you have proven yourself invaluable to Westguard Keep and the Alliance at large. Pick something from the treasury, boy! It's the least we can do!", objectives = "Kill Necro Overlord Mezhen. Then, return to Captain Adams at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11237] = { id = 11237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gjalerbron Attack Plans", description = "These plans detail an imminent attack upon Westguard Keep. It would appear that the frost wyrm, Glacion, who circles overhead is to be used for the offensive.\n\nSurely Mage-Lieutenant Malister would be of some assistance in this matter. Deliver the plans to him at the keep to the south.", progress = "What?! Plans for an attack upon the keep?\n\nA FROST WYRM?!!!", completion = "{name}, we can't let this come to pass!", objectives = "Deliver the Gjalerbron Attack Plans to Mage-Lieutenant Malister at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11238] = { id = 11238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frost Wyrm and its Master", description = "You were right to bring this to me, {name}. You must venture to Gjalerbron and slay that wyrm and its master, Wyrmcaller Vile!\n\nEven now, as we speak here, the frost wyrm may be on its way.\n\nHowever, if I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!\n\nAnd {name}, please bring me the horn. We wouldn't want it falling back into the wrong hands.", progress = "Is the attack averted? Are the frost wyrm and its master destroyed?\n\nDid you retrieve the horn?", completion = "Wow, that horn is cold!\n\nOnce again you've saved Westguard Keep from certain doom. What a curious man you are, {name}. If only there were more of you.\n\nWell, this certainly calls for a reward. Which do you prefer?", objectives = "Slay Wyrmcaller Vile and use the Wyrmcaller's Horn to call down and slay Glacion. Then, return with the horn to Mage-Lieutenant Malister at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11239] = { id = 11239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service to the Light", description = "Your service has been exemplary, {name}, but there is something that is troubling me: the Scourge.\n\nThe Light cannot abide their presence, and neither shall we. I hope that it is not asking you too much, but I would have you return north to Gjalerbron and crush the unholy Scourge in that vile lair! Be sure to check for them in the Waking Halls beneath Gjalerbron as well.\n\nPurification is the key to salvation, my child. Make us proud!", completion = "<The priest quietly mouths a benediction for you.>\n\nBless you, {name}, you have answered my prayers. Stand proudly in the Light, chin held high with the knowledge that your actions were most holy!\n\nI'm certain that the church's coffers can yield up something of use to you.", objectives = "Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Father Levariol at Westguard Keep of your success.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11240] = { id = 11240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leader of the Deranged", description = "So, I hate to say it, pal, but while you were out, the captain took a keener interest in that place.\n\nLooks like he wants my old Explorers' League boss in there dead. My guess would be that we're gearing up for an offensive to clear out the rest of them, and the captain wants their head lopped off, as it were.\n\nDo me a favor? Head back into Whisper Gulch and put an end to Squeeg Idolhunter. From what I remember, my guess would be that he's in the cave in the northwest corner.", completion = "<The sapper grumbles as if he wishes that you hadn't succeeded.>\n\nThe captain will be pleased to hear of your success.\n\nYou know, since you've been such a good sport in dealing with this Whisper Gulch business, why don't you take your pick of one of these?", objectives = "Slay Squeeg Idolhunter and then report back to Sapper Steelring at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11241] = { id = 11241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trail of Fire", description = "Thanks for bailing me out of this mess, {name}.  I was not looking forward to what these Alliance scumbags had in store for me.\n\nLet's get out of here and see if we can get back at them somehow.  Is that a campfire over there?", completion = "Apothecary Hanes is alive?  You burned the Alliance supplies to the ground?  He must've gotten a real kick out of that.\n\nAt any rate, the Royal Apothecary Society is in your debt, {name}.  We thank you from the bottom of our black, black hearts.", objectives = "Escort Apothecary Hanes out of the Derelict Strand. Report to Apothecary Lysander at Vengeance Landing in Howling Fjord when you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11242] = { id = 11242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.", progress = "You have something for me, good {name}?", completion = "What is this?  The tome of Thomas Thomson?  But that is the name of the Horseman before he was cursed!  Does this mean that he is finally free?  Does this mean he will no longer torment the good people of Azeroth?\n\nWhat a joyous day!  {name}, your feat will live long with us.  The children, and their children, will sing your name!", objectives = "Take the Tome of Thomas Thomson to the Costumed Orphan Matron in Goldshire, Kharanos or Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11243] = { id = 11243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If Valgarde Falls...", description = "If Valgarde falls, our primary supply line into Northrend will cease to exist. From there it'll only be a matter of time before we're all servants of the Lich King. Now I don't know about you, but I've got a wife and three kids back in Elwynn and I'll be damned if I'll go down without a fight.\n\nThe situation here is critical and we can use all the manpower you're able to muster. Get to the front gate and help the guards defend the city against the invading monsters!", progress = "The fate of the world may very well rest with us.", completion = "You gave our defenders the extra support they needed, {name}. Morale is higher than ever now, thanks to you. I think they'll be able to handle the remaining onslaught on their own. I've got bigger plans for you...", objectives = "Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to slay 12 Dragonflayer Invaders or Dragonflayer Worgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11244] = { id = 11244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescuing the Rescuers", description = "We'd been here for a month when those malformed giants appeared out of thin air. We were ill-prepared for any sort of attack and paid dearly for our complacency. An entire archaeology team was lost and several townsfolk were abducted and taken to the ruins. We've been on the defensive ever since.\n\nTo make matters worse, the scouts we sent to rescue our people have been harpooned by the vrykul and left for dead in the forest directly north of Valgarde. Dislodge those harpoons and free our scouts!", completion = "What the vrykul did to our scouts was a gruesome display of savagery. It was a scare tactic, meant to weaken our resolve... to send us running in fear for our lives.\n\nIt failed.\n\nWe are going to show those monsters what it means to wage war against the Alliance!", objectives = "Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 8 Valgarde Scouts that have been impaled and left for dead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11245] = { id = 11245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers of Certain Doom", description = "<Sir/Ma'am>, as we move through Skorn, we have to bring down those towers!\n\nIf you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom for us!\n\nHowever, we do have it within our means to call in cannon volleys from Westguard Keep. To do so, we need to get close enough so that you can lob a smoke flare atop of them.\n\nJust don't get too close!", completion = "Excellent targeting, sir! I'll have to remember to buy a round for the cannoneers back at the keep.", objectives = "The Westguard Sergeant has informed you that using the Sergeant's Flare to target all four of the towers at Skorn for cannon volleys would be advisable.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11246] = { id = 11246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gruesome, But Necessary", description = "We've had reports that these vrykul can rise from the dead; not unlike the Scourge, but a different kind of undeath.\n\nLet's not take any chances.\n\nHere, take my machete. As we move through this place, you'll need to carve up the remains of the vrykul that we take down. I'd do it, but I have a sensitive stomach.\n\n<The sergeant smirks.>\n\nI spent all morning sharpening it, so it should do the job.", completion = "Well, sir, I have to say that you went about that particular business with a bit of zeal.\n\n<The sergeant looks at you warily.>\n\nAnyway, if you don't mind, I'll be taking my machete back now. It looks dull and we wouldn't want you to accidentally slip and carve me up, too.", objectives = "The Westguard Sergeant has asked you to use The Sergeant's Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11247] = { id = 11247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn Skorn, Burn!", description = "Captain Adams gave me strict instructions to make sure that a good deal of infrastructure damage was inflicted on this site.\n\nHowever, since you're in charge out here, that's at your discretion, <sir/ma'am>.\n\nMay I suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn? All we have to do is get inside each and throw this torch.", completion = "Very good, sir. That couldn't have been done without your help.\n\nI'm sure that the captain will be pleased with my report on the matter once we're done here.", objectives = "The Westguard Sergeant has orders that you should use the Sergeant's Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11248] = { id = 11248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Skornful Wrath", description = "{name}, I must now ask you to undertake an operation so hazardous, so deadly, that only you can see it through.\n\nThe vrykul fortress, Skorn, sits on our eastern border. My scouts inform me that those 'giants' are poised to strike us, and with my forces scattered all over the fjord, I don't have the men to take the place by force.\n\nInstead, you're going to use your cunning. I've sent a sergeant ahead with the details. Show this command insignia at Skorn and he'll reveal himself and follow your orders.", completion = "A pleasure to meet you, sir! I look forward to working with you.\n\nSpeaking of which, we have a great deal to do.", objectives = "Captain Adams has asked you to use the Westguard Command Insignia at Skorn, and then to speak with the Westguard Sergeant.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11249] = { id = 11249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Ascension!", description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.", progress = "Yes? How may I help you, my child?", completion = "Yes, my son, that is ominous-looking, and you obviously had the right of it.\n\nThank you for bringing this scroll to me. I am very keen to study its implications. If I were to hazard a guess, I would say that these vrykul have a way to transcend death; at least those that are worthy.\n\nBy defeating the Winterskorn thane, you proved him unworthy. The Light only knows what he would have become, and what terror he might have rained down upon us, had you not slain him.", objectives = "Present the Vrykul Scroll of Ascension near the Thane's Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you're sure that Father Levariol at Westguard Keep will be interested in seeing the scroll.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11250] = { id = 11250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Hail the Conqueror of Skorn!", description = "We -- well, you -- have done everything that we were sent here to accomplish <sir/ma'am>. I must say that it's been a pleasure taking orders from such a fine, young {race}.\n\nThe captain is sure to want to hear of your success, but if you decide to stay out here for whatever reason, I am at your disposal.", progress = "I gather that since you're here, Skorn is no more?", completion = "That's unbelievably good news! I knew that you could pull it off, {name}!\n\nAt least someone around here can produce results!\n\nWell, this calls for a reward. Go ahead, take your pick; the treasury is open to you.", objectives = "Return the Westguard Command Insignia to Captain Adams at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11251] = { id = 11251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Legs", description = "It's come at great cost, but we've completed our inspection of the site.\n\nThe news isn't good. Nearly everyone has been slain or captured. Only a few veteran guards remain unaccounted for.\n\nThe scouts have done all we can here. You must pick up where we've left off.\n\nSounds of a skirmish are coming from up the hill to the northeast. Have a look, {class}. We can only hope there are some who have survived, and that they may have some intel we can use against this enemy.", completion = "Late though ye may be, it's good to see a friendly face.\n\nNow stop standin' around with yer thumb up yer nose. there's work to be done!", objectives = "Scout Valory wants you to investigate the sounds of battle coming from the northeast of Wyrmskull Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11252] = { id = 11252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Utgarde!", description = "Listen up, youngster. I've put down me share of these creatures - and your share too fer that matter. Here be what ya need to know....\n\nThe vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple.\n\nThere's one they esteem though, goes by the name of Ingvar. I dunno why they be seekin' his praise, but bring him down and you'll deal a mighty blow to their spirit.\n\nThen, perhaps, we'll have a chance....", progress = "Good to see you're well, {name}.\n\nWe've had about as many casualties as we can handle.", completion = "Outstanding!\n\nThis could be the turn of luck we've all been hoping for.\n\nWell done, {name}!", objectives = "Defender Mordun has tasked you with the execution of Ingvar the Plunderer who resides deep in Utgarde.\n\nYou are then to bring his head to Vice Admiral Keller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11253] = { id = 11253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sniff Out the Enemy", description = "Now that this rascal's belly's full, maybe he will be more willing to cooperate.  Here's his leash, just come get him from his cage whenever you're ready to take him.\n\nI don't know what Anselm expects you to find, but look for clues wherever it is that the dog takes you.", completion = "This scaly scroll is covered in stark painted images.  You've a feeling this is the sort of thing the kennel keeper had in mind when he asked you to look for clues.", objectives = "Use the Plaguehound Leash near the plaguehound cages at Vengeance Landing and look for clues at the location you're led to by the Plaguehound Tracker.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11254] = { id = 11254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragonskin Map", description = "Upon closer inspection, the scroll appears to be a heavily-illustrated map of the fjord.  The location of various villages are depicted in what seem to be tribal symbols.\n\nThe location of Vengeance Landing is marked with a disproportionately large skull.\n\nThis map will almost certainly be of military value to High Executor Anselm.", progress = "You've something to show me, {class}?", completion = "<The high executor looks at the map intently, occasionally looking up at landmarks around the Fjord.>\n\nHere's the eastern coastline over here.  The Dragonflayer and Winterskorn villages are here and here... and this must be us over here, marked for death.", objectives = "Bring the Dragonskin Map to High Executor Anselm in Vengeance Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11255] = { id = 11255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoners of Wyrmskull", description = "This battle is far from over, {name}. If our people are still alive inside that village, someone has to go and get 'em.\n\n<Vice Admiral Keller nods at you.>\n\nHead north and enter Wyrmskull Village. Once there, look for our people. If they are imprisoned you'll need to find a way to break them out.\n\nMaybe they'll have some more information about what it is that we're actually fighting.", completion = "Those soldiers you rescued had a good bit of information for us. These monsters call themselves 'vrykul.' The tribe that's taken up residence in Wyrmskull Village is led by a mystic named Yanis who himself is an underling of another vrykul known as Ingvar the Plunderer.", objectives = "Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 3 Captured Valgarde Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11256] = { id = 11256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skorn Must Fall!", description = "{name}, the vrykul fortress, Skorn, sits to the south. Its strange giants have recently awakened and have begun to spread, attacking us wherever they can.\n\nMy scouts inform me that they are poised to strike at us here, but I do not have the strength to repel such a force. Instead, we will prepare to leave north to less dangerous lands.\n\nI ask that you use your cunning to buy us time. I've sent a brave ahead with the details. Show this emblem at Skorn and he'll reveal himself and do all he can to aid you.", completion = "It will be interesting to learn about your people, {class}, while fighting alongside you.\n\nShall we proceed?", objectives = "Chieftain Ashtotem has asked you to use the Winterhoof Emblem at Skorn, and then to speak with the Winterhoof Brave.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11257] = { id = 11257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gruesome, But Necessary", description = "Our elders say that these vrykul may be able to rise from the dead; not unlike the walking dead you call the Scourge, but a different kind of undeath.\n\nWe should not take any chances.\n\nHere, take my machete. As we move through this place, carve up the remains of the vrykul that we slay.\n\nI spent the morning sharpening it, so it should cleave even through their thick bones.", completion = "Have you done that before? Your skill with my machete seemed practiced.\n\n<The brave looks at you warily.>\n\nI'll take it back from you now, {class}.", objectives = "The Winterhoof Brave has asked you to use The Brave's Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11258] = { id = 11258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn Skorn, Burn!", description = "Chieftain Ashtotem ordered me to destroy many buildings here.\n\nHowever, you are in charge, so it falls to your hands, {name}.\n\nI suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn. All we have to do is get inside each and set them ablaze with this torch.", completion = "<The brave nods at you in clear approval of your handling of the torch>\n\nLet these vrykul feel the heat of the land. Let them know the fear they would instill in others!", objectives = "The Winterhoof Brave suggests that you use the Brave's Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11259] = { id = 11259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Towers of Certain Doom", description = "As we move through Skorn, we must destroy the towers.\n\nIf you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom.\n\nHowever, we can call in wind rider air strikes from Camp Winterhoof. To do so, we need to get close enough so that you can lob a smoke flare atop of them.\n\nJust don't get too close.", progress = "Getting too close to those towers is certain death as long as those casters are up there.", completion = "You have a strong arm, {name}.\n\nIt looks as if those wind riders finally made themselves useful instead of just standing around and drinking all day.", objectives = "The Winterhoof Brave has informed you that using the Brave's Flare to target all four of the towers at Skorn for air strikes would be advisable.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11260] = { id = 11260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Ascension!", description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.", progress = "Yes? How may I help you, child?", completion = "Yes, that is ominous-looking, and you obviously had the right of it.\n\nThank you for bringing this scroll to me. I will study its implications. If I were to hazard a guess, I would say that these vrykul have a way to transcend death; at least those that are worthy.\n\nBy defeating the Winterskorn thane, you proved him unworthy. Who knows what he would have become, and what terror he might have rained down upon us, had you not slain him?", objectives = "Present the Vrykul Scroll of Ascension near the Thane's Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you're sure that Greatmother Ankha at Camp Winterhoof will be interested in seeing the scroll.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11261] = { id = 11261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Conqueror of Skorn!", description = "You have done everything that we were sent here to do, {class}. I must admit that you fight well. Your people are not as strange as I first thought.\n\nChieftain Ashtotem is certain to want to hear of your success, but if you decide to stay out here for whatever reason, I will continue to fight at your side.", progress = "What news do you bring of Skorn, {name}?", completion = "That is good news indeed! You have given us some breathing room to further our preparations for leaving.\n\nPlease, take one of these as a sign of our appreciation.", objectives = "Return the Winterhoof Token to Chieftain Ashtotem at Camp Winterhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11262] = { id = 11262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ingvar Must Die!", description = "Of our entire recon party, only I remain.\n\nThese vrykul are relentless fighters. Given their numbers and their savage tactics, our only hope is to bring down their leader and pray it brings chaos to their ranks.\n\nIngvar is his name. Bring me his head!", progress = "Gird up, {race}.\n\nThere's much work to be done. This is just the tip of the iceberg, so to speak.", completion = "Excellent work, {name}. With their leader removed, our efforts against these vrykul should be more successful.\n\nService such as this cannot go unrewarded!", objectives = "Dark Ranger Marrah has asked you to kill Ingvar the Plunderer inside Utgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11263] = { id = 11263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dealing With Gjalerbron", description = "My longrunners that have lived to return have informed me that the vrykul have awakened at their main fortress to the west.\n\nIt is a forbidden place known as Gjalerbron. The longrunners tell me that the vrykul are performing strange rituals.\n\nWe cannot allow this to continue.\n\nAre you willing to continue to assist us? Will you kill the vrykul at Gjalerbron before they finish whatever they are doing and attack us here?", completion = "You have my thanks, {name}. I know that you do not have any duty to me or my people.\n\nWhat you say about that place troubles me still, and I sense that our culling is not quite at an end.", objectives = "Chieftain Ashtotem has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Camp Winterhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11264] = { id = 11264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Necro Overlord Mezhen", description = "The dead ones are at Gjalerbron and they have necromancers with them?\n\nWe must eliminate the leader of these necrolords.\n\nDo whatever it takes, {name}, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized.\n\nWe cannot afford to see the vrykul successful in whatever they are doing with these undead creatures!\n\nLook for Mezhen on the platform in the rear right section of Gjalerbron.", completion = "<Chieftain Ashtotem breathes a sigh of relief.>\n\nThat should take some of the pressure off.\n\n{name}, time and again you have proven your value to the taunka of Camp Winterhoof. Please, choose something from our bounty. I insist.", objectives = "Kill Necro Overlord Mezhen. Then, return to Chieftain Ashtotem at Camp Winterhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11265] = { id = 11265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Keys and Cages", description = "From the little we know, the vrykul are conducting unnatural rites in an 'awakening' ritual to the west in Gjalerbron.\n\nThey're using living sacrifices to fuel their rituals.\n\n{name}, you must stop this. It matters not who or what is in those cages, they must be freed. I would guess that the vrykul hold the keys.\n\nThe last thing we need is more of those strange vrykul threatening us, or worse, them wakening something even more evil....", completion = "A great stone is lifted from my shoulders to hear of your success. And I smile to know that some you freed were taunka.\n\nPlease, take this as a gift for what you have done. I shall see to the health of those you freed.", objectives = "Greatmother Ankha has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to her at Camp Winterhoof when you manage to do so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11266] = { id = 11266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gjalerbron Attack Plans", description = "These plans detail an imminent attack upon Camp Winterhoof. It would appear that the frost wyrm, Glacion, who circles overhead, is to be used for the offensive.\n\nSurely Celea Frozenmane would be of some assistance in this matter. Deliver the plans to her at the camp to the east.", progress = "What?! Plans for an attack upon our camp?\n\nFROM A GREAT WYRM IN THE SKY?!!!", completion = "{name}, we cannot let this come to pass!", objectives = "Deliver the Gjalerbron Attack Plans to Celea Frozenmane at Camp Winterhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11267] = { id = 11267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frost Wyrm and its Master", description = "Your instincts were right to bring this to me, but my wind riders cannot fight a dragon. You must venture west to Gjalerbron and slay the frost wyrm and its master, Wyrmcaller Vile!\n\nEven now it may be on its way!\n\nIf I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!\n\nAnd {name}, bring me the horn. We wouldn't want it falling back into the wrong hands!", progress = "Is the attack averted? Is the great death wyrm and its master destroyed?\n\nDid you retrieve the horn?", completion = "This horn is as cold as the land... perhaps even colder!\n\nYou have saved Camp Winterhoof from certain doom, not that we'll be staying here much longer. What a curious man you are, {name}. Perhaps you {race}-types from over the ocean are not so bad after all.\n\nThis calls for a reward. Which do you prefer?", objectives = "Slay Wyrmcaller Vile and use the Wyrmcaller's Horn to call down and slay Glacion. Then, return with the horn to Celea Frozenmane at Camp Winterhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11268] = { id = 11268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Walking Dead", description = "Your assistance to us has been tremendous, {name}, but there is something that is troubling me: these so-called Scourge.\n\nThe spirits of the land and air, the waters and the fire below the world, would not abide their presence, but seem to do nothing about them. We will see to it that they are dealt with!\n\nPerhaps it is asking too much, but I would have you return west to Gjalerbron and destroy the unnatural Scourge in that vile lair. Be sure to check in the Waking Halls below Gjalerbron as well!", completion = "<The greatmother nods her approval of your actions.>\n\nThank you, {name}, you have done what is right and you have bought us a little more time to finish our preparations for leaving. We will soon make the journey north.\n\nI am too old; when we go, I will not be able to carry everything with me. Would you like to take one of these?", objectives = "Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Greatmother Ankha at Camp Winterhoof of your success.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11269] = { id = 11269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down to the Wire", description = "The vanguard of the Alliance force will be arriving within days. The soldiers will be expecting their winter gear to be prepared, but I've still got more cloaks to make.\n\nI've been using spotted hippogryph down for the cloaks' linings, but my stock won't last!\n\nYou've got to help me, {name}. Captain Adams will have my hide if those cloaks aren't ready in time! Bring me all the down you can find out there. It's dropped to the ground by molting hippogryphs flying over the wilderness around the fort.", progress = "Have you brought any of that down? I could really use it...", completion = "Thank goodness! This should be enough to finish the order in time. Of course, I won't sleep until the troops arrive, but that's far better than risking Captain Adams' wrath.\n\nI've heard the stories they tell about him!", objectives = "Gil Grisert wants you to bring him 10 clumps of Spotted Hippogryph Down.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11270] = { id = 11270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War is Hell", description = "We're slowly finishing off the remnants of Stormwind's North Fleet stationed on this coast.  The bodies to the west are a testament to how brutal this confrontation has been.\n\nThis does not happen to bother my refined aesthetics, but it does present a danger to our lives.\n\nIn the lands of the Lich King, the dead are a weapon that can rise against us at any point in time.  Take this torch - you're going to make sure that doesn't happen.", completion = "I'm glad you've proven you can follow orders.  If I had a copper piece for every arrogant fool in shiny armor to come here and think they're above the chain of command... well, I'd have a few gold.\n\nNow that you've demonstrated a measure of discipline, I have other tasks more suitable for someone of your caliber.", objectives = "High Executor Anselm at Vengeance Landing wants you to take the Burning Torch and use it to burn 10 of the corpses littered to the west of town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11271] = { id = 11271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hasty Preparations", description = "The down of the spotted hippogryph is prized by my people and used for everything from fletching to ceremonial clothing. We're making preparations to leave the post, so this is the last chance I'll get to gather it this season.\n\nWith your help, I'll have enough to make sure everyone has the equipment they need for the long trek into the hills. Conditions worsen very quickly up there and a storm can blow in without warning.\n\nThe down can be found all over the ground in the area surrounding the post.", progress = "Have you gathered any of the down?", completion = "With your contribution, we'll be well prepared for the journey. I haven't much to offer you for your help, but I will give you a choice of some of my spare combat gear.", objectives = "Ahota Whitefrost at Camp Winterhoof wants you to bring him 10 clumps of Spotted Hippogryph Down.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11272] = { id = 11272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Score to Settle", description = "This elf prince thinks he can come to my town, insult my queen, kill my men and get away with it? He thinks we're going to stand by while the hordes of Utgarde build up to launch an attack?\n\nNot in a million years.\n\nYou're going to walk right into Utgarde and kill him. I want Arthas to know that we've arrived and we're playing for keeps.\n\nReport to Dark Ranger Marrah inside Utgarde Keep when the deed is done and she'll tie up any... loose ends.", completion = "Revenge feels good.  To think that this is but a taste of what's to come.\n\nArthas will get what he deserves soon enough.  Then and only then will I die a happy man.", objectives = "High Executor Anselm wants you to slay Prince Keleseth inside Utgarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11273] = { id = 11273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Human League", description = "We were on the brink of an archaeological breakthrough when those monsters attacked! Sadly, I was the only one to make it back to Valgarde. Now I don't know if my crew is dead or alive, but the artifacts we uncovered on that dig must be found!\n\nIf you're heading into Wyrmskull Village, will you keep an eye out for my team? If there's any hope of recovering that information, we must pursue it!\n\nSearch for Pulroy first. He was the last one I saw before I made my escape.", completion = "You've found Pulroy. A bit too late it seems.\n\nWhile looking over the corpse you see a journal clenched tightly in Pulroy's death grip. Upon examining the journal you read what appears to be the scribbling of a dying dwarf.", objectives = "Search Wyrmskull Village for Pulroy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11274] = { id = 11274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zedd's Probably Dead", description = "To whomever finds this journal:\n\nThese bloodthirsty monsters have taken up residence in the ruins of Wyrmskull. What they want or why they're here is a mystery. In any case, the artifacts are not safe with those beast-men around.\n\nZedd and I made a new discovery while hiding out: a cipher to decode the tablets! Unfortunately Zedd and I were separated late last night. He had the cipher. Tablets were with Glorenfeld and Daegarn. Location unknown...\n\nFind Zedd.\n\n-Pulroy", completion = "You've found Zedd. You're no doctor but the prognosis for Zedd is most assuredly negative.\n\nIt looks as if they were preparing to feed him to the worgs. Gruesome...", objectives = "Search Wyrmskull Village for Zedd.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11275] = { id = 11275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Horn", description = "My people have been hunting the giant yeti of these hills for generations and I will be participating for the first time this year. It will probably be the last before we leave the post forever.\n\nTo prepare for the hunt, I must fashion a loud horn from the horns of the dire rams that roam the snowy areas near our camp. The elders tell me the sound mimics the mating call of the female yeti, but I have my doubts.\n\nBring me the best dire ram horns you can find, {name}, and I'll select one from among them.", progress = "Have you brought any suitable horns?", completion = "These are all fine horns, {name}. Let me examine them and select the one I will use in the hunt.\n\nI'll give the rest to the craftsmen for use in their carvings.", objectives = "Nokoma Snowseer at Camp Winterhoof wants you to bring her 6 Undamaged Ram Horns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11276] = { id = 11276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Then There Were Two...", description = "There's no sign of the cipher on Zedd. After carefully searching the area you discover some writing in the dirt:\n\n\"Glor and Dae inside catacombs. Have cipher and tablets.\"\n\nPerhaps you should head into the catacombs located just north of here and search for Glorenfeld and Daegarn. The bridge crossing the worg pit will lead you right to the tunnel leading down into the catacombs.", completion = "About bloody time! Pulroy and Zedd are dead.\n\nAnd Daegarn...\n\n<Glorenfeld shakes his head.>\n\nTaken by the Dragonflayer chieftain into the depths of these catacombs. I overheard that oversized mongrel mention something 'bout a sacrifice to the \"Dread King.\"\n\nThe cipher is hidden away in Daegarn's grimy beard.\n\nWhat? Dwarves hide things in their beards all the time!", objectives = "Search the Utgarde Catacombs for Glorenfeld.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11277] = { id = 11277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Depths of Depravity", description = "They're keepin' Daegarn locked up in a cage at the large fightin' ring nearby. From what I've gathered, the Dragonflayers bring out their prisoners to battle against their most powerful gladiators. They dump the losers in the basement where Scourge necromancers turn 'em into ghoulies! It's horrifying!\n\nBut first things first! The tablets are strewn about all across this dungeon. Let's get those recovered before you go off tryin' to be a hero.", progress = "Check every nook and cranny!", completion = "You've done well, mate. Now that we've secured the tablets we can try and save Daegarn's life and recover the cipher that will help us decode the meaning behind these ancient relics!\n\nI'll hold on to these tablets, you rescue Daegarn.", objectives = "Glorenfeld at the Utgarde Catacombs wants you to collect 10 Wyrmskull Tablets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11278] = { id = 11278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Valgarde", description = "'Tis a shame we lost two of our best dwarves while uncovering these relics. They sacrificed their lives to keep this information safe.\n\n<Glorenfeld wraps the cipher and tablets in a tattered cloth.>\n\nTake these back to Valgarde. McSorf will know what to do with the find.\n\nAs for me? I'll be alright on my own. I've gotten this far in one piece!", progress = "You're back!", completion = "Sorting these tablets out is going to take some time. All I can gather from a precursory study is that whatever used to be here was an ancestor of the humans. Those vrykul things probably killed 'em all off. Anyhow, we'll know more once I get these relics set up.", objectives = "Take Glorenfeld's Package to Beltrand McSorf at Valgarde Port.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11279] = { id = 11279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Eggs and Whelps", description = "This new plague that we're working on is wonderful and I think we should expand its testing.\n\nHow about testing it on proto-whelps?!\n\nJust think of the possibilities. The ability to infect not only humanoids, but extend our reach to any creature!\n\nHere, I've hoarded an extra plague canister for the right time and place, and you look like the right person.\n\nSpray the eggs at Ember Clutch to the northwest, then get specimens from the plagued proto-whelps that hatch.", progress = "Without those samples, how am I to tell if this latest strain of the plague can be expanded for use on all sorts of creatures?", completion = "What?! No, this can't be right.\n\nCURSES!\n\nThis batch of the plague doesn't seem to have had any real effect on the proto-whelps at all other than to make them glow green!\n\nMy dream of using the plague upon anything we come into contact with seems to have gone up in smoke!", objectives = "Plaguebringer Tillinghast has asked you to collect 10 Plagued Proto-Whelp Specimens and deliver them to him at New Agamand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11280] = { id = 11280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draconis Gastritis", description = "Wait, that gives me an idea! What if it didn't kill the whelps because it was sprayed on the outside of their eggs?\n\n{name}, we have to get the plague inside of them!\n\nI know! I've got some plagued meat here. Take it to the Ember Clutch and get them to eat it!\n\nBut no, we're thinking too small. Let's get one of the proto-drakes flying overhead to come down and eat it.\n\nYes!\n\nStay close to the meat and observe what happens. Yes, it might attack you, but such is the price of progress.", completion = "NOOOOOOOOOOOOOOOO!!!\n\n<The plaguebringer begins to cry.>\n\nAll of my hopes... all of my dreams, ruined!\n\nLeave me, {name}. Leave me to my despair. I'm nothing.\n\nHere, you might as well take all of my worldly possessions. When the rest of the apothecaries hear of my failure, I'll be done for and won't need them anyway.", objectives = "Plaguebringer Tillinghast at New Agamand wants you to use Tillinghast's Plagued Meat to attract down a Proto-Drake and observe its reaction to eating the stuff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11281] = { id = 11281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mimicking Nature's Call", description = "The horn has been roughed out, but before I make the traditional carvings, I want to be certain that it will work. Ahota tells me that he tests his horns at the foot of the frozen waterfall to the northeast of the post. Ahota tells me that our hunters have used the acoustics of frozen water in this way for generations. I can't wait to learn more!\n\nWill you help me test out the horn? If I've done everything right, you may even attract a yeti, so be prepared! Bring the horn back once you've tested it.", completion = "<Nokoma listens to your report from the test.>\n\nI'm relieved that the horn worked so well... maybe too well if what you're saying was true. You're sure the beast spoke? I don't know if I can go on with the hunt if that's true. I'll have to speak with Chief Ashtotem about it.\n\nThis horn may end up being merely decorative, but that won't diminish its worth. Thank you for all your help, {name}.", objectives = "Test the Carved Horn and then return to Nokoma Snowseer at Camp Winterhoof with the results.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11282] = { id = 11282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lesson in Fear", description = "When you've been in lots of fight like Gorth, you learn that to beat enemy good you have to make them really scared to die!\n\nBut these vrykuls not afraid.  You kill one and another comes... screaming louder and with a bigger weapon than the one before.\n\nOnly thing that makes vrykuls afraid is when we kill the biggest and baddest vrykul of all.\n\nGo fight the Winterskorn across the blockade until hero vrykuls show up!  Then you kill them dead and put queen's flag on corpses.  They must learn to fear!", completion = "You do some good killings over there.  I see vrykul men fall and get stabbed with Sylvanas flag.  Our side doing good!", objectives = "Gorth wants you to kill Ulf the Bloodletter, Oric the Baleful and Gunnar Thorvardsson and drive the Forsaken Banner through their corpses. Slay Vrykul across the Forsaken blockade until they appear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11283] = { id = 11283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baleheim Bodycount", description = "Them vrykuls just keeps coming and coming out from town west of here.  No end in sight!\n\nGorth has an idea.  You go INSIDE town and kill them Winterskorn there.  THEN they stop coming here!", completion = "You must have lots of practice with doing killings.  You almost as good as Gorth!", objectives = "Sergeant Gorth wants you to kill 16 Winterskorn Vrykul inside Baleheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11284] = { id = 11284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Yeti Next Door", description = "Maybe if the sentries won't help me, you will? I'm the foreman of the mine just across the bridge. My men are mining ore for the weapons our expeditionary force will need to carve a path into the Grizzly Hills.\n\nA giant yeti has invaded the mine, blocking the tunnel we need to expand! We've tried yelling at him and smoking him out, but nothing's worked.\n\nMaybe you could rouse it from its sleep with a meal of meat from the frosthorn rams in the snowy areas around town? Please? We're desperate!", completion = "You've done it? By the Light, you're a walking miracle! I was beginning to think I'd personally have to explain to Captain Adams why his men's weapons weren't ready in time!", objectives = "Foreman Colbey at Fort Wildervar wants you to defeat Shatterhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11285] = { id = 11285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baleheim Must Burn!", description = "Killing the Winterskorns maybe not enough.  Maybe we burn their houses too!  Uh... and their bridges.  We should burn whole town to be safe!\n\nYou take this torch.  Go to Baleheim, to the west, and burn EVERYTHING!  That teach them good.", completion = "I guess you burned everything.  I see couple of spots not burning... but is close enough for Gorth.", objectives = "Sergeant Gorth wants you to go to Baleheim and use Gorth's Torch to burn 1 Winterskorn Dwelling, 1 Winterskorn Watchtower, 1 Winterskorn Bridge and 1 Winterskorn Barracks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11286] = { id = 11286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Artifacts of Steel Gate", description = "I came out here for a different reason; an old friend of mine has been calling to me in my dreams. But now that I see these small things with their machines making a big hole in the ground, it makes my blood boil.\n\nFrom what I can see, these dwarves, as they are known, are digging up artifacts; artifacts that could be important to our past.\n\nI want you to go down there and get these things for me. Don't let any of those dwarves stand in your way.", progress = "How many artifacts have you managed to gather from this Steel Gate?", completion = "<The sage grunts his approval at your actions on his behalf.>\n\nPerhaps I will be able to find the time soon to study these artifacts and come to an understanding of their significance.\n\nBut now there are more pressing matters to attend to.", objectives = "Sage Mistwalker has asked you to collect 10 Steel Gate Artifacts. When you have all of them, return to him at Steel Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11287] = { id = 11287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Sage Mistwalker", description = "{class}, I grow worried that my son, Sage Mistwalker, has been gone for such a long time. The land is cruel and deadly.\n\nHe spoke of a recurring vision that he had of a wolf, and went west with a small group of longrunners to seek its source. I believe the name of the place he mentioned was Steel Gate.\n\nWill you find him? I want to make sure that no ill has befallen him.", completion = "My mother should not concern herself with my safety. But, I thank you for coming, stranger.\n\nSince you are here, perhaps you will help me with a few things?", objectives = "Greatmother Ankha has asked you to check on the condition of Sage Mistwalker. She believes him to be at or near Steel Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11288] = { id = 11288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shining Light", description = "<Ares gasps for air as he tries to speak.>\n\nI am an envoy of the Argent Crusade, charged with a sacred duty.\n\nOur forces were decimated in the Plaguelands. By the light of dawn, the artifact was cleansed and made pure once more. So many perished in the wake of its redemption.\n\nThere is still a chance... still time.\n\nThe artifact was hurled into the den of the fallen, far below us. Guarded by the unmerciful dead.\n\n<Ares' body glows with blinding light.>\n\nLight. Will. Protect. You.", progress = "<Ares is unconscious.>", completion = "You feel compelled to place the sacred blade next to the body of Ares.\n\nUpon doing this you are once again blinded by light.", objectives = "Ares the Oathbound in the Utgarde Catacombs wants you to recover the Sacred Artifact.\n\nThis is a timed quest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11289] = { id = 11289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guided by Honor", description = "<Ares smiles.>\n\nGlory to the Light. You have done it!\n\n<Ares coughs.>\n\nTake the artifact and return it to Valgarde. Lord Irulon Trueblade awaits its return.\n\nFight with honor, friend. Always. Honor.\n\n<Ares dies.>", progress = "By the Light!", completion = "Many men and women died to recover this blade. Alas, I fear valiant Ares will not be the last.\n\nBut you do the Light's work, hero. This sacred blade will be wielded by Lord Tirion Fordring himself. Even now the Argent Crusade works toward Icecrown. Lord Fordring has vowed that he will tear down the walls of the cursed place himself! And with the blade, he just might stand a chance against the Lich King.\n\nLord Fordring remains our greatest hope.", objectives = "Return the Sacred Artifact to Lord Irulon Trueblade at Valgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11290] = { id = 11290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonflayer Battle Plans", description = "While we were able to gather very little information as to the whereabouts of Ingvar, we do know that Yanis resides in a cave next to the worg pit inside Wyrmskull Village.\n\nIntelligence gathered from the rescued soldiers indicates that Yanis guards Dragonflayer battle plans.\n\nI need you to go back to Wyrmskull and recover those plans. Kill any vrykul that get in your way - including Yanis!", progress = "Have you recovered the Dragonflayer battle plans?", completion = "<Vice Admiral Keller glances over the plans.>\n\nOutstanding! By the looks of things, there are many more vrykul villages in the fjord. A different tribe of vrykul is preparing an assault on Westguard Keep. Hell, for all I know it may already be too late. We haven't heard from Westguard in days. Either way, we must alert Westguard!", objectives = "Vice Admiral Keller at Valgarde Port in the Howling Fjord has asked that you bring him the Dragonflayer Battle Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11291] = { id = 11291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Westguard Keep!", description = "<Vice Admiral Keller rolls up the battle plans.>\n\nWe've got all the information we need to keep Valgarde protected. You must take these battle plans to Westguard Keep, located on the western fjord cliff wall. Speak with the flight master assistant, Emilune Winterwind. She will put you on the back of a gryphon headed towards Westguard.\n\nOnce there, find Captain Adams. He's the one in charge. Adams will know what to do with these plans.", progress = "Valgarde has not fallen? That's a surprise.\n\nMust be due to your help. It sure wasn't because of Keller.", completion = "<Captain Adams takes the plans from you.>\n\nI'm glad you decided to come over. My advisors and I will need some time to study these plans. In the meantime, we can use all the help we can get!", objectives = "Take the Dragonflayer Battle Plans to Captain Adams at Westguard Keep in the Howling Fjord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11292] = { id = 11292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preying Upon the Weak", description = "Glad to meet you. I've come here from the Grizzly Hills to do business with your cohorts. My people maintain a large outpost there, and you'd do well to visit it when you head north.\n\nI've set up traps in the woodlands and snowy areas around here. With the meat and the furs from the creatures they capture, I'll have plenty to barter with the townspeople.\n\nI can offer you a share of my profits if you're willing to help gather prey from the traps. Beware though, you won't be the only predator out there.", progress = "I hope you haven't returned empty-handed. I thought we had a deal.", completion = "<Trapper Jethan inspects the creatures you've brought him.>\n\nNicely done. Some of these will fetch a better price than others, but I should have plenty to trade with the locals.", objectives = "Trapper Jethan at Fort Wildervar wants you to bring him 8 pieces of Trapped Prey.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11293] = { id = 11293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for the Barleybrews!", description = "We need to get the word out about the Barleybrews at Brewfest.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.  I'll make things easy though, I'll lend you a racing ram for 4 minutes.  Use the reins to let him go, but try not to tire him out.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the Barleybrews?", completion = "Well done!  That kinda shouting is sure to bring business our way.\n\nAnd we promised you a reward, here it is.  The Barleybrews keep their word.\n\nOh, and come back any other day if you want to help spread the good name of Barleybrew.", objectives = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11294] = { id = 11294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for the Thunderbrews!", description = "It's time to let people know that the Thunderbrew have heard their cries for good brew.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.\n\nWe'll make it easy though.  We'll lend you a ram for 4 minutes.\n\nBe careful with going too fast though since you won't find any apple crates in Ironforge...  We can't take the chance of helping out the Barleybrew messengers.", progress = "Did you let everyone know that the Thunderbrews are here at Brewfest?", completion = "Good job!  That'll show those arrogant Barleybrews.\n\nWell we promised you a reward and here it is.  We Thunderbrew reward you with prizes, the Barleybrew reward you with foul odors and false promises.\n\nYou chose wisely.\n\nIf you want to keep making the right choice, stop by another day and help us spread the word.", objectives = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11295] = { id = 11295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Offensive Begins", description = "No one seems to know very much about the vrykul.  Our records show no signs of activity in their lands for centuries.  Yet here they are, just as we move against Arthas.\n\nThe map you retrieved makes it clear that we'll have to defeat them if our forces are to get any further into Northrend.\n\nOne of my best sergeants, an abomination known as Gorth, oversees the blockade beyond the lift.  Assist him in launching a pre-emptive strike on Baleheim.  If a vrykul attack occurs, it will be launched from there.", completion = "You come to help?  Good... good...\n\nGorth was getting tired of killing vrykuls all day.  Help is welcome!", objectives = "Speak to Sergeant Gorth at the blockade near the elevator west of Vengeance Landing in Howling Fjord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11296] = { id = 11296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rivenwood Captives", description = "Something, most likely the walking dead known as the Scourge, has agitated the creatures hereabouts.\n\nWhile escorting the sage here, we lost most of our hunting force to the riven widows -- huge and deadly spiders, which inhabit the Rivenwood to the north.\n\nI must stay here to protect the small force we have left, but you... you could see if my longrunners are still alive, trapped within the riven widow's cocoons.\n\nWould you do this, stranger?", completion = "That was a very brave act, {class}. I did not know that your people were capable of such selflessness.\n\nNext time I will heed the warnings of my elders and steer clear of the Rivenwood. I advise you to do the same.", objectives = "Longrunner Skycloud has asked you to free his 7 Winterhoof Longrunners. Once you have managed to do so, return to him at Steel Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11297] = { id = 11297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping Watch on the Interlopers", description = "Even the earth cannot hold back the tide of death washing over it. Corpses walk the land, spreading their putrefaction with alarming speed.\n\nA small expedition has made its way up the western cliffs and rests near Whisper Gulch. Take a look for yourself, {name}. See if you can learn their purpose and dissuade them from bringing their poisons into our lands. Travel southwest from the post, toward the cliffs overlooking the western beach. Their camp will be west of the excavation at Steel Gate.", completion = "Ah, yes, the reclusive bison-men of the north. I've seen them skulking about, believing themselves unseen. I suppose they fancy this land theirs? Well, that's but one of many things that will change shortly.\n\nI wasn't expecting any company, but while you're here on that fool's errand, you might as well make yourself useful.", objectives = "Speak to Apothecary Malthus at the Apothecary Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11298] = { id = 11298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's in That Brew?", description = "To the southeast is an area called Whisper Gulch. It's overrun with members of the Explorers' League who've gone mad! They attacked our caravan as it passed through the area, and they've harried our foraging parties as well.\n\nI must know what's causing this madness! I suspect that whatever they're drinking from the kegs scattered around the gulch contributes to their insanity. I want you to steal the kegs from those dwarves while they're busy mining away.", progress = "Did you get those kegs or not?", completion = "<The apothecary pours out a tankard of the beverage for himself.>\n\nWell, here I go!", objectives = "Apothecary Malthus at the Apothecary Camp wants you to bring him 5 Dwarven Kegs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11299] = { id = 11299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ring of Judgment", description = "You might have already seen the room where Daegarn is being held while you were gatherin' the tablets. It's through this corridor and then down a set of steps. Daegarn will be in the room at the bottom of the steps - locked up tight!\n\nGet down there and find him. At the very least you might be able to get the cipher from him.", completion = "Yep. You found me. Woopedy-do!\n\nAnd no, I don't have the cipher. My beard was the first thing those beasts checked! Oluf's the one that's got it now. He's the chieftain of the gladiators.", objectives = "Find Daegarn in the Ring of Judgment located inside the Utgarde Catacombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11300] = { id = 11300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stunning Defeat at the Ring", description = "Oluf will come out if you defeat the other gladiators. That's 'bout the only way we're getting' that cipher back. Put on your whompin' boots and get busy in the Ring of Judgment. If you do manage to get the cipher back, return it to Glorenfeld o'er near the entrance to these catacombs.\n\nMe? Don't worry about me! We're on the brink of discovering the missing link to human-kind!", progress = "Daegarn? The cipher?", completion = "Fascinating tale! Something is actually judgin' these things? To what end?! For what purpose?\n\nWell, never mind that nonsense. Someone else can figure out that stuff. We got the cipher and the tablets back - and only two fatalities in the whole ordeal.", objectives = "Defeat the gladiators at the Ring of Judgment and face Oluf the Violent. Defeat Oluf and recover the Ancient Cipher.\n\nReturn the Ancient Cipher to Glorenfeld at the entrance to the Utgarde Catacombs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11301] = { id = 11301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brains! Brains! Brains!", description = "Has Malthus drawn you in with his blather about beer kegs and crazy dwarves?\n\nI'm not questioning that the dwarves are crazy, but I don't think stealing their beer is going to do any good.\n\nWhat we need is brains. Lots of brains. We'll get down to the bottom of this mystery in no time, and perhaps even find a new component for the plague.\n\nTake this saw, go southeast into the Whisper Gulch, and kill yourself some dwarves. Use the saw to help you harvest the brains and bring them back here.", progress = "Did you get those brains? If not, I want my saw back. You'd better not walk off with that saw.", completion = "These brains are beautiful! Gorgeous, even! They're exactly what I need.\n\nThank you for your help, {name}. Now I'll show Malthus the truth his beer goggles couldn't reveal.", objectives = "Apothecary Grick at the Apothecary Camp wants you to bring him 12 Deranged Explorer Brains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11302] = { id = 11302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enigmatic Frost Nymphs", description = "When we first scouted locations for the fort, we encountered hostile creatures at two of the glades here in the north. When we passed the snow-covered one directly south of the town, the dryads there watched us with interest, but did not attack.\n\nWe were tired and worn down by the weather. They could've easily killed several of our men, but they didn't.\n\nPerhaps, in reaching out to them, we might discover unexpected allies. Are you willing to travel to the Frozen Glade and make contact with them?", completion = "<Lurielle listens as you introduce yourself.>\n\nIt is good to finally meet you, {name}. We have long hoped that you and the other newcomers might send representatives. We don't often venture beyond the borders of our glades, especially amid the changes the land is going through.", objectives = "Speak with Lurielle at the Frozen Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11303] = { id = 11303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ambush", description = "The vrykuls in Baleheim is completely defeated, no doubt about it.  But still their leader stays in town and won't give up.\n\nGorth sends Lydell and his assassins to make good ambush to the northwest.  You talk to Lydell and figure out how to get Vrykul chieftain to come out.  Then you kill him.  You kill him real good.", completion = "We all showed up to the party, but the guest of honor stayed at home.", objectives = "Speak to Lydell at Lydell's Ambush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11304] = { id = 11304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Agamand", description = "I'm afraid our equipment isn't exactly the best here at Vengeance Landing.  After all it's a military controlled outpost.\n\nI will need you to take a sample of this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond Baleheim south and then west.  They have better equipment there - he will know what to do.\n\nYou must hurry, {name}.  Our enemies are stronger and more numerous than us.  We need to develop a viable weapon against them!", progress = "Yes, {name}?", completion = "This strain is far from worthless, my friend!  Those fools at Vengeance Landing have had all the answers right under their own noses!", objectives = "Bring Lysander's Strain to Chief Plaguebringer Harris in New Agamand in western Howling Fjord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11305] = { id = 11305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tailor-Made Formula", description = "We've been spraying down the vrykul village of Halgrind for weeks now and the vrykul just won't drop dead.\n\nLet's face it, {name}, by now our Plague has been exposed to humans, dwarves, dogs, livestock... you name it.  As our strains adapt to their hosts, more impurities get thrown in the mix.  What we need is a strain made custom for the vrykul's biology.\n\nHalgrind's chieftain fled the town after we took it over; you'll find him west of here.  As a patriarch of the Dragonflayer clan, his blood is ideal.", progress = "Have you obtained the sample I require, {name}?", completion = "This will do.  It's time for some real apothecary work now, {name}!", objectives = "Obtain the Dragonflayer Patriarch's Blood from Thorvald at Thorvald's Camp and bring it to Chief Plaguebringer Harris in New Agamand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11306] = { id = 11306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apply Heat and Stir", description = "You've done well so far, {name}.  I'd like to teach you some of my more advanced techniques, so that you gain a better understanding of the plague.\n\nTake this empty flask and fill it with blood from the cauldron to my left.  Mix it with the plague samples to my right until you obtain a well balanced mix.", progress = "How is your experiment going, {name}?  Let me know if you have any questions behind the science involved!", completion = "Excellent!  You are an apt pupil, {name}.\n\nNow comes the fun part.  Deployment!", objectives = "Fill the Empty Apothecary's Flask at the Cauldron of Vrykul Blood, then mix the Flask of Vrykul Blood with Harris's Plague Samples nearby until you've obtained a Balanced Concoction.\n\nReturn to Chief Plaguebringer Harris when you've completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11307] = { id = 11307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Test", description = "Now that we have a strain of the plague that has adapted to vrykul carriers, we really ought to test it on our specimens in Halgrind.  If all goes according to plan, they will disintegrate immediately as the plague devours their innards!\n\nYou will find Halgrind north of here.  Our plaguebringers are deploying the previous strain there - shouldn't be hard to spot.", completion = "The plague didn't disintegrate our subjects?  Are you certain, {name}??!\n\nThere must be an external factor we're not accounting for... perhaps the low temperatures of this climate?  Perhaps... a mutation in the strain!", objectives = "Venture into Halgrind and use the Plague Spray on 10 Plagued Dragonflayer Vrykul. Return to Chief Plaguebringer Harris to report the results.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11308] = { id = 11308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time for Cleanup", description = "Being the practical man that I am, I'm going to declare our research here a success.  After all, what army can't be stopped by turning its rank and file against each other?\n\nI will send word of our achievements to Vengeance Landing soon enough.  But first I need you to take care of cleaning up our experimentation site.\n\nSee \"Hacksaw\" Jenny about making you a custom abomination.  One packing some explosive power if you catch my drift.", completion = "What do you want?  Can't you see I'm in the middle of something?", objectives = "Speak to \"Hacksaw\" Jenny in New Agamand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11309] = { id = 11309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parts for the Job", description = "So Harris wants a demolition job, eh?  Yeah, I can help out.\n\nYou're gonna have to get me some parts, though.  I can't afford to use up my choice components on something that's gonna get blown up.\n\nFirst of all, I'm going to need shoveltusk ligaments... way better than the human kind.\n\nI will also need a pound of flesh.  A fellow known as Anton sells cheap meat.  He travels up and down the road to the west.", progress = "You get my components yet?", completion = "Excellent!  Yes, yes, these will do just fine!", objectives = "\"Hacksaw\" Jenny in New Agamand wants you to obtain 6 Shoveltusk Ligaments and 1 Fresh Pound of Flesh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11310] = { id = 11310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warning: Some Assembly Required", description = "Well, here you are!  Our friend's going to be somewhat... unstable.  So I suggest not putting him together until reaching Halgrind.\n\nOnce you're there, use the abomination to round up as many vrykul as you can before self-destructing.\n\nCome back with whatever's left once you're done.  I can always use more body parts!", progress = "Are you done with the cleanup in Halgrind?", completion = "Great job, {name}.  Say, you wouldn't be looking for something more... permanent, would ya?  I could sure use some help around these parts!", objectives = "Use the Abomination Assembly Kit in Halgrind and round up plagued Vrykul with your Mindless Abomination. Slay at least 20 and return to \"Hacksaw\" Jenny in New Agamand when you're done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11311] = { id = 11311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suppressing the Elements", description = "If you are to survive here, as we have, you must learn to face the environment's challenges head on. The elements will claim your life if you're not vigilant, as the proliferation of elementals in these northern hills shows.\n\nWe must cull the elementals one last time before we can leave this place. Are you willing to aid us while we continue to make preparations?\n\nYou must kill any iceshard elementals or howling cyclones you encounter in the snowy hills surrounding the outpost.", completion = "The influence of the elemental spirits has receded, but it will return. We've bought ourselves the time we need to complete our tasks here and take our leave.", objectives = "Wind Tamer Kagan at Camp Winterhoof wants you to kill 8 mountain elementals. You may kill either Howling Cyclones or Iceshard Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11312] = { id = 11312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frozen Glade", description = "For generations, my people have told tales of frost nymphs cavorting in glades hidden away in the wilderness. I used to search for them as a child, against the advice of my parents, until I nearly froze to death.\n\nThese days, it isn't necessary to comb the forests for them. They've decided to reveal themselves for reasons I can only guess, but I don't think the change can be ignored. Venture southeast to the Frozen Glade and seek out the nymphs, but beware; you will pass the Twisted Glade on your way.", completion = "<Lurielle listens as you introduce yourself.>\n\nIt is good to meet you, {class}. My sisters have often watched the taunka search the forests for us, but we are forbidden by our queen from interacting with outsiders. You only see us now because the land has become unsettled and many of my sisters are in danger.", objectives = "Speak with Lurielle at the Frozen Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11313] = { id = 11313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits of the Ice", description = "The ice elementals surrounding our glade were once our companions, but a volatile and destructive force has swept through the land, turning them against us!\n\nThis is but one of the horrors my sisters and I have endured. We have revealed ourselves to you in the hope that you will help us stave off the decay that has crept into our glades and poisoned our sisters!\n\nWe've been gathering the cores of the ice elementals and keeping them safe so that one day, we might be able to restore them. Will you help?", progress = "Have you recovered any of the cores?", completion = "<Lurielle accepts the cores from you quietly.>\n\nThank you, {name}.\n\n\n\nI promise, my friends, I will do all I can to restore you.", objectives = "Lurielle at the Frozen Glade wants you to bring her 15 Icy Cores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11314] = { id = 11314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Sisters", description = "To the southwest was a glade that used to look much like this one. Mysterious forces and alien magics are reshaping the land. The glade has thawed, the sisters living there driven mad by the sudden change.\n\nWe thought to reach out to them, but they attacked us. I fear many may be beyond saving, but I cannot give up hope.\n\nTake my pendant, travel southwest to the Vibrant Glade, and use it to try to free my sisters.", completion = "So there is hope for my sisters?\n\n<Lurielle looks away from you, then down at the ground.>\n\nI feel guilty for not thinking of the pendant sooner. We might have saved even more of the sisters.", objectives = "Lurielle at the Frozen Glade wants you to use her pendant on 7 Chill Nymphs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11315] = { id = 11315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Vines", description = "The sisters who lived in the Vibrant Glade, to the southwest, used to tend to gorgeous beds of scarlet ivy, but the same force that has driven them mad has transformed their beloved ivy.\n\nThe vines now grasp at the feet of the unwary, or lash at any who approach the glade. Before we can reclaim the glade, the vines must be tamed and uprooted.\n\nClear as much of the ivy as you are able. It has already begun to grow out of control.", completion = "Thank you for your help, {name}. The Vibrant Glade was once a beautiful place, and when we return to it, we shall make it so again.", objectives = "Lurielle at the Frozen Glade wants you to kill 8 Scarlet Ivy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11316] = { id = 11316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spawn of the Twisted Glade", description = "The glade to the west has been transformed into a hideous place called the Twisted Glade. Horrible beasts dwell among the trees, stones, and pool of the glade.\n\nI cannot guess where the creatures came from or what horrible forces animate them, but they must be dealt with!\n\nI fear that if they are allowed to dominate the glade, they will poison it beyond redemption. Clear the glade of these creatures who murdered our sisters.", completion = "You have done well, {name}. If we'd had allies like you when the land first began to change, perhaps we might have been able to preserve some of what we've lost.", objectives = "Lurielle at the Frozen Glade wants you to kill 10 Thornvine Creepers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11317] = { id = 11317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing", description = "We braved the Rivenwood because of my troubled dreams concerning my worg life-friend, Ulfang. He has called out for help, and you must go to him.\n\nBut, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nFirst, you must cleanse your inner turmoil.\n\nThere is a shrine that sits at the top of Frostblade Peak, northeast of Camp Winterhoof. A single path leads up to it from the western base of the mountain.\n\nMeditate there and then return to me.", completion = "Already I can sense the change within you.\n\nAre you ready for what comes next?", objectives = "Sage Mistwalker at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11318] = { id = 11318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams? Well I hope you're ready for speed. BUT before I let you loose in the world, you'll need to show me that you can handle these fine creatures.\n\nSo here's the deal: I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each. If you need instructions how to handle the ram, talk to my apprentice, Pol Amberstill.", progress = "Were you able to handle the speed?", completion = "Nice work there!  It takes time to get the hang of controlling your ram.  But once you do, you'll wish every ram was a racing ram.\n\nWhat's that? \"Where's my reward?\"  Ha Ha Ha... you got to ride the fastest ram around!  You want more?  Well how about this...\n\nYou've been rewarded with the chance to help other people around Brewfest.  There's plenty of work, and rewards, for an eager, young, ram racer.", objectives = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11319] = { id = 11319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeds of the Blacksouled Keepers", description = "The glade to the northwest, now the Twisted Glade, used to be home to a number of keepers of the glade. Together with the sisters, they saw to the glade's upkeep.\n\nWhen the glade changed, the sisters died, but somehow the keepers managed to survive. Now, they seed the land with poisonous spores that wither healthy greenery.\n\nI'll give you one of the cores from the ice elementals. Once you've destroyed a spore, use the ice crystal to freeze it and keep it from regenerating.", completion = "The ice core worked well for you? I'll have to remember that. I'm certain the keepers will not stop just because we've destroyed their work once.", objectives = "Lurielle at the Frozen Glade wants you to freeze 8 Spores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11321] = { id = 11321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did Someone Say \"Souvenir?\"", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", objectives = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11322] = { id = 11322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cleansing", description = "Of late I've had nightmares concerning a worg named Ulfang. He has called out for help, and you must go to him.\n\nHowever, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nBut first, you must cleanse your inner turmoil through meditation.\n\nThere is a shrine that sits at the top of Frostblade Peak, far to the northeast. A single path leads up to it from the western base of the mountain.\n\nMeditate there to cleanse yourself and then return to me.", completion = "Already I can sense the change within you.\n\nAre you ready for what comes next?", objectives = "Watcher Moonleaf at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11323] = { id = 11323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger.\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", completion = "You look and smell different... you are not one of my pack. Tell me your story; I have nothing but time while I am trapped in here.", objectives = "Sage Mistwalker has asked you to seek out and help Ulfang in the Rivenwood.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11324] = { id = 11324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Mistwalker that I am once more the alpha worg!", progress = "{name}, you have returned. What news of Ulfang?", completion = "Garwal was not a worg at all! I know of these creatures... they are called worgen.\n\nBut, Ulfang indicated that it came south from the Grizzly Hills? Odd. There aren't any worgen there.\n\nI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.\n\nPlease, you must accept this as a sign of gratitude.", objectives = "Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Sage Mistwalker at Steel Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11325] = { id = 11325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger!\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", completion = "You look and smell different... you are not one of my pack. Tell me your story; I have nothing but time while I am trapped in here.", objectives = "Watcher Moonleaf has asked you to seek out and help Ulfang in the Rivenwood.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11326] = { id = 11326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Moonleaf that I am once more the alpha worg!", progress = "{name}, you have returned. What news of Ulfang?", completion = "Garwal was not a worg at all! The thing you describe him turning into sounds a lot like a worgen!\n\nBut, Ulfang said that it came south from the Grizzly Hills? Odd. There aren't any worgen there.\n\nI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.\n\nPlease, you must accept this as a sign of gratitude.", objectives = "Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Watcher Moonleaf at Steel Gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11327] = { id = 11327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Package Retrieval", description = "Well darn, we need some of that plague-stuff.\n\nI know!\n\nWhile you were destroying the vats, I happened to spy one of the apothecaries from New Agamand being pulled into Halgrind by the vrykul down in there. Poor fella'.\n\n{name}, I'd bet anything that apothecary has the goods on him. Think you could go into Halgrind and retrieve his package?", progress = "That place looks like a nightmare. Vrykul or not, no one deserves to be the victim of the Royal Apothecary Society.\n\nGlad I'm standing safely over here. You find that package yet?", completion = "Holy... what the hell?! Look at this stuff!\n\nWe need to get this back to the keep a.s.a.p.!", objectives = "Scout Knowles has asked you to retrieve the Apothecary's Package from inside Halgrind. Once you have it, return to the scout at the Ember Spear Tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11328] = { id = 11328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Forsaken Intel", description = "Right, so I think you should get this stuff over to Peppy Wrongnozzle back at the keep. She's something of an amateur alchemist, but she's the only one we've got.\n\nOne thing about Peppy; she does love her drink. So, you'll likely find her at the tavern 'soaking up the atmosphere'.\n\nI'm sure she'll know what to do.", progress = "Yeah, whadya want ...hic?", completion = "Oh... hey, that'sh different!\n\nOkay, let me shee that shtuff. I jusht love tinkering with alchemy!\n\nInteresting, interesting... here, I think I know jusht what to do. A little mixing of that with the jusht the right amount of thish.\n\nYou know, I think a little dash of this rotgut will help, too ...hic!", objectives = "Scout Knowles has asked you to deliver the Apothecary's Package to Peppy Wrongnozzle at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11329] = { id = 11329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'll Try Anything!", description = "I never want to see another barrel of salted fish as long as I live! Filling barrels day in and day out, and there are still more to be filled!\n\nI wish I hadn't used up all that bait I bought from Nat Pagle. Worked like magic, it did. Now I'm lucky if I can catch a fish an hour!\n\nI hear the northern barbfish make pretty good bait, but who's crazy enough to dive into a freezing cold lake and hack up the water plants in search of them? Not me... but maybe, just maybe, I can persuade you to...", progress = "You look like you're still in one piece. Get any of that bait?", completion = "Well, these certainly are ugly enough, but I suppose I don't care if it actually works. I'll be relieved once the expedition has passed through and I can go back to simply fishing for my dinner.", objectives = "Christopher Sloan at Fort Wildervar wants you to bring him 5 Northern Barbfish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11330] = { id = 11330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absholutely... Thish Will Work!", description = "Voila, inshtant plague vacshine!\n\nBut I sure as heck am not going to try thish on myself. And I know you don't want to be my tesht shubject!\n\nOh, I've got... I've got an idea!\n\nWe've got a vrykul prishoner being held down in the cells under the keep. Why don't you take thish mix I whipped up down there, and get that giant to drink it ...hic?!", completion = "Huh? Well that sucks! Darn, I made thingsh worsh. In fact, I think I perfected their plague for them ...hic!\n\n<Peppy grimaces and takes a huge gulp of whatever noxious brew she's been drinking.>\n\nWell, I wash hoping that it wouldn't come down to thish, but it looks like there'sh no alternative ...hic.", objectives = "Peppy Wrongnozzle at Westguard Keep has suggested that you take her Peppy's Special Mix and administer it to the Dragonflayer Vrykul Prisoner to witness its results.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11331] = { id = 11331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "You Tell Him ...Hic!", description = "Here'sh the deal. I'm not going to the captain with thish news. I'm an amateur alchemist, thish ishn't my job, and I'm on break!\n\nBeshides, he'sh a big grumpkin... and you know him better than I do!\n\nSho, jusht go up into the keep and tell him. I'm sure he'll be reashonable about the whole thing ...hic.\n\n<Peppy turns back to her drinking.>", completion = "Yes, {name}, what is it now?\n\nWHAT?!! A Forsaken super plague that melts you in no time?\n\nYou oozed my vrykul prisoner?\n\n\n\nAlright, I know what we need to do. Or rather, what YOU need to do!", objectives = "Peppy Wrongnozzle has suckered you into giving the bad news about the Forsaken plague to Captain Adams. Visit him at Westguard Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11332] = { id = 11332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Plague This!", description = "The Royal Apothecary Society thinks they're going to perfect a new plague to melt us down where we stand?!\n\nNot on my watch!\n\nGet out to the courtyard and speak with Greer Orehammer. He's got a gryphon and some bombs ready for you. I want you to bomb the plague tanks at New Agamand to smithereens!", progress = "Those plague tanks destroyed, yet? That new plague looms over our heads like certain death, {class}!", completion = "Nicely done, {name}, nicely done!\n\n\n\nThat'll show those good-for-nothing Forsaken to think about messing with us!\n\nI'd say you've earned yourself something from the treasury!", objectives = "Captain Adams has ordered you to get 5 bomb hits on the Plague Tanks at New Agamand. Do not return to him at Westguard Keep until you have accomplished that.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11333] = { id = 11333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the World of Spirits", description = "While the Explorers' League may discern bits and pieces of the past through their archaeological findings and the Vice Admiral might extract some knowledge of the present through brute force, the truth lies with the spirits.\n\nWith the proper reagents I am able to see into the spirit world. It is there that the past, present and future of Northrend resides.\n\nIf you wish to learn more, I will require my reagent pouch. It was lost in a ship that is now at the bottom of Daggercap Bay, just east of here.", progress = "Have you found my reagent pouch?", completion = "A bit worse for the wear but still functional.\n\n<Thoralius reaches into the pouch and removes some odd looking roots.>\n\nNow to place them in the fire and inhale!\n\n<Thoralius throws the roots into the smoldering incense burner.>\n\n<Thoralius inhales deeply. His body begins to quiver.>\n\nWha... What... It cannot be... I cannot...", objectives = "Thoralius the Wise at Valgarde wants you to find his Reagent Pouch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11334] = { id = 11334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "He Shoots, He Scores!" }
quests[11335] = { id = 11335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, {name}.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", objectives = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11336] = { id = 11336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, {name}, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", objectives = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11337] = { id = 11337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "The fight against the Horde knows no boundaries, {name}.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.", objectives = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11338] = { id = 11338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11339] = { id = 11339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, {class}, go to Arathi Basin and crush the enemy.  Victory to the Horde!", completion = "You've brought great honor to the Horde, {name}.  Your victory today will ensure a thousand victories tomorrow!", objectives = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11340] = { id = 11340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, {name}.  Earn great honor by heeding the call of the brave Frostwolf warriors.", objectives = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11341] = { id = 11341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Eye of the Storm", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!", objectives = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran,  or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11342] = { id = 11342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, {name}.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11343] = { id = 11343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Echo of Ymiron", description = "The spirit world has fallen under the sway of the Lich King. Fearsome creatures made of pure nightmare now stand watch over the realm of the elements. I sense that these val'kyr are guarding a terrible secret.\n\nI am too old and weak to survive another journey. You must go in my place, {name}.\n\nTake this incense burner to Wyrmskull Village and use it to enter the spirit world. Find the large dwelling in the northeast! Avoid the val'kyr at all costs lest they make you a permanent fixture in their world.", completion = "I do not understand. The creatures that you saw looked like the vrykul that are attacking Valgarde?", objectives = "Thoralius the Wise wants you to search Wyrmskull Village while you are in the spirit world and find information about the Secrets of Wyrmskull.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11344] = { id = 11344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anguish of Nifflevar", description = "All that we know of the vrykul indicates that they only recently appeared in Northrend. Why, then, are we seeing vrykul in visions that date back 15,000 years? Surely if the vrykul had previously existed in Northrend we would have known.\n\nYou must press on to Nifflevar. To get there you must go northeast, through Wyrmskull Village, and take the path leading up through the dam. Nifflevar is on the bluffs of the fjord.\n\nUse the incense burner once you arrive at Nifflevar and search the area for clues.", completion = "Human children born of vrykul? And Ymiron ordered the deaths of all human born offspring?\n\n<Thoralius goes silent for a moment.>\n\nAs much as I wish to deny what is so plainly presented to me, I cannot. There is no extinct \"missing link\" to humans as the Explorers' League proposed. The vrykul are the missing link. They are the progenitors of humanity.", objectives = "Thoralius the Wise wants you to search Nifflevar while you are in the spirit world and find information about the Secrets of Nifflevar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11345] = { id = 11345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prizes for Pellets" }
quests[11346] = { id = 11346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of Runes", description = "The vast rocky area to the southeast, Giants' Run, has been overrun by Iron Dwarves. Scouts have reported seeing the dwarves coaxing stone giants from the ground, then carving runes on them.\n\nI can't fathom their motives, but I suspect they're somehow trying to turn the giants into weapons. The iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me, {name}.", progress = "Have you recovered the book?", completion = "<Prospector Belvar browses the book of runes.>\n\nHmm... there's so much here. I'm going to need some time to study it, and if we hope to understand these runes, we'll need to try to make our own.", objectives = "Prospector Belvar at Fort Wildervar wants you to bring him The Book of Runes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11348] = { id = 11348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", completion = "You've done well in defeating Binder Murdis, but the Iron Dwarves won't give up easily.\n\nWe've made a lot of progress in understanding how they manipulate runes. Perhaps next time we encounter them, our knowledge will give us an advantage.", objectives = "Prospector Belvar at Fort Wildervar wants you to test the Rune of Command and defeat Binder Murdis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11349] = { id = 11349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Runes", description = "I've got a set of picks, hammers, and chisels with me, but they won't work for carving these runes. The tools used by the Iron Dwarves are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nI believe I know how it works, but without a set of those tools, I can't be certain. Look for kits resembling mine near the Iron Dwarf pavilions at Giants' Run and bring them to me.", progress = "Have you returned with those tools?", completion = "<Belvar handles the tools carefully.>\n\nI'm going to try these out. If we're to understand the Iron Dwarves' motives and defeat them, I need to know exactly what the runes are doing.", objectives = "Bring a set of Iron Rune Carving Tools to Prospector Belvar at Fort Wildervar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11350] = { id = 11350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Book of Runes", description = "Chieftain Ashtotem dispatched me on a scouting mission to Giants' Run, a broad, rocky plateau to the southeast, past the Frozen Glade.\n\nThe area has been taken over by Iron Dwarves who seem to be altering the giants as they emerge from the earth.\n\nThe iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me. It's the only way we'll understand their plans.", progress = "Have you recovered the book?", completion = "<The longrunner browses the book of runes.>\n\nI'm no loremaster, but I have some familiarity with the language of the Iron Dwarves. I think the runes they're carving on the giants are derived from their spoken language, but there are some differences.", objectives = "Longrunner Pembe at Camp Winterhoof wants you to bring him The Book of Runes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11351] = { id = 11351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Runes", description = "I think I've figured out what the Iron Dwarves are doing. The tools they use are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nIf I had a set of those tools, I could mimic the runes in the book. I captured one of these boxes from one of the pavilions at Giants' Run, but it was empty. Look for similar boxes and recover a set of tools from them.", progress = "Have you returned with those tools?", completion = "<Pembe examines the tools.>\n\nThese are more delicate than I'd thought. Allow me a moment to try them out.", objectives = "Bring a set of Iron Rune Carving Tools to Longrunner Pembe at Camp Winterhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11352] = { id = 11352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", completion = "You've done well in defeating Binder Murdis, but the Iron Dwarves won't give up easily.\n\nAs my people move north, I'm certain we will encounter the Iron Dwarves again. Next time, we will be prepared to thwart them before they can dig in.", objectives = "Longrunner Pembe at Camp Winterhoof wants you to test the Rune of Command and defeat Binder Murdis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11353] = { id = 11353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Got the work shirt" }
quests[11354] = { id = 11354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Nazan's Riding Crop", description = "Today I have a buyer who is interested in a piece that's held by the mount of Illidan's herald. I, of course, speak of Vazruden the Herald and his dragon mount, Nazan.\n\nIf you want the finder's fee that I offer in return, find them flying above the Ramparts at Hellfire Citadel and return with the dragon's riding crop.\n\nMy sources tell me that the item in question is personally held by the dragon. It is said that Nazan refuses to allow Vazruden to strike him with it.", progress = "The riding crop please.", completion = "Another soon-to-be satisfied customer. It looks like it's in fine condition. You are to be rewarded.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to obtain Nazan's Riding Crop. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11355] = { id = 11355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. What their ultimate destination is, I do not know.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey.\n\nUse this pick to deactivate the runes on the giants' corpses and return with your findings.", completion = "<Researcher Aderan listens to your findings.>\n\nThe runes for \"north\" and \"west\" appeared multiple times? There's a highly reinforced command to move in that direction, but the runes are more than propulsion. Something is attracting them, but what?", objectives = "Researcher Aderan at Fort Wildervar wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11356] = { id = 11356, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Costumed Orphan Matron", description = "During Hallow's End, human orphanages have organized trips for their orphans to visit Alliance countryside villages.  Those poor children would love to see a real {class} like yourself!\n\nWhy don't you visit them?  You'll find orphans at Goldshire in Elwynn Forest, Kharanos in Dun Morogh and Azure Watch in Azuremyst.  Speak to the children's ward, a costumed orphan matron, and she'll introduce you to the children.", completion = "You're here to visit the children!  Wonderful!  They have known such heartache in their short lives.  It is good that they see real heroes like you.  It really lifts their spirits!", objectives = "Speak with a Costumed Orphan Matron in either Goldshire, Kharanos or Azure Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11357] = { id = 11357, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masked Orphan Matron", description = "For Hallow's End, several orphans were taken on a trip to different Horde villages. The orphan matrons thought it would be good for them to see real heroes adventuring in the field.\n\nWhy don't you visit them? A brave {class} like yourself could strengthen their spirits with tales of your valor! Go to Razor Hill in Durotar, Brill in Tirisfal Glades, or Falconwing Square in Eversong Woods. Speak with the masked orphan matron and she'll introduce you to the children.", completion = "The children love to watch heroes at their work.  It is my hope that, one day, each of these orphans will grow into a strong member of the Horde, and ultimately die in glorious battle!\n\nAh, thoughts of such a fine fate brings mist to my eyes...", objectives = "Speak with a Masked Orphan Matron in Razor Hill, Brill, or Falconwing Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11358] = { id = 11358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lodestone", description = "If we can locate what's luring the giants northwest, we might be able to stop them before they reach their destination.\n\nAlthough I was able to decipher many of the runes on the samples you brought me, the ones I don't know concern me the most. When I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn.", completion = "<Aderan listens as you describe your findings.>\n\nOf course! This Megalith must be the key to the Iron Dwarves' plans. We must destroy it before their plan comes to fruition!", objectives = "Researcher Aderan at Fort Wildervar wants you to compare the Rune Sample with the Broken Tablet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11359] = { id = 11359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be the most powerful of the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. After the expeditionary force arrives, our soldiers will be able to isolate and defeat the remaining giants and oust their Iron Dwarf masters from their camps.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", completion = "You've done well in felling Megalith, but I wonder about his final words.\n\nYou're sure he said the Stoneforge?\n\nI know of no place with that name, but it sounds like a word with origins in the titans. What plans do the Iron Dwarves have for such a thing? This bears watching, {name}, for we must find it before the Iron Dwarves' plan comes to fruition.", objectives = "Defeat Megalith and return to Researcher Aderan at Fort Wildervar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11360] = { id = 11360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade.  Do you want to help?\n\nNorth of here, guards set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here, or the one near the fires.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", progress = "Hello, {name}.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the north!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", objectives = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11361] = { id = 11361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The grunts set up a fire training area outside the village. These days, Razor Hill's buildings often catch fire -- you should lend a hand and train as a fire fighter!\n\nHead west out of Razor Hill, then turn right as you pass the village's wall. Find the training area, then grab buckets and toss them on the practice fires.", completion = "Well done, {name}!  Children, take a good look at this {class}. Grow strong and brave like him and one day you too will fight for the Horde.", objectives = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Razor Hill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11362] = { id = 11362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Keli'dan's Feathered Stave", description = "There is no accounting for taste. Take my most recent buyer for instance.\n\nThere is a blood orc within Hellfire Citadel known as Keli'dan the Breaker. He bears a most mundane stave; certainly nothing to take a second glance at. And yet, this is what my customer wishes.\n\nWho am I to say no?\n\nIf you desire my compensation, you will find him and his stave within the Blood Furnace.", progress = "We are speaking again... you must have the stave.", completion = "Perhaps I will have new feathers tied onto it before shipping it on to the buyer. I'm certain with so many arakkoa hereabouts it will not prove difficult. A small matter, and nothing to detract from your reward in any case.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to obtain Keli'dan's Feathered Stave. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11363] = { id = 11363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Bladefist's Seal", description = "Today I have a very wealthy collector in need of something very unique indeed.\n\nWarchief Kargath Bladefist carries upon his person his seal of command, which he uses to sign all official documents. I want you to retrieve it for me.\n\nYou will find him deep within the Shattered Halls. No doubt you will have to wade through a veritable army to get to him. I have no doubt that you will succeed.", progress = "I have heard it whispered that the warchief has weapons in place of his hands. Is this true?", completion = "Truly a daring acquisition that the bards should put pen to parchment for. Here, you have more than earned this.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to obtain Bladefist's Seal. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11364] = { id = 11364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Shattered Hand Centurions", description = "Do you question your master? Neither does Mah'duun.\n\nThe blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel.\n\nIf you want the bounty, you will not return until you have slain them all.", completion = "Very well, you have earned your bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", objectives = "Nether-Stalker Mah'duun has tasked you with the deaths of 4 Shattered Hand Centurions. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11365] = { id = 11365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. I know nothing of their goals, nor of their destination.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey. Fell some of these giants.\n\nTake this pick with you and use it on the corpses of the runed stone giants. It will deactivate the runes. Once you've tested enough giants, return to me with your findings.", completion = "<The sage listens to your findings.>\n\nThe runes for \"north\" and \"west\" appeared over and over? I'm not an expert in these runes, but the repetition of them suggests a strong command.\n\nThese carvings are more than passive directions, though. They seem to pull the giants toward something, but what?", objectives = "Sage Edan and Camp Winterhoof wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11366] = { id = 11366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lodestone", description = "We must find what's luring the giants northwest, so we can stop them before they reach their destination.\n\nWhile the rune samples gave us some clues, the unknown runes worry me.\n\nWhen I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn about the identity of this lodestone.", completion = "<Edan listens as you describe your findings.>\n\nMegalith? A literal transcription from the tablet! This Megalith must be the centerpiece of the iron ones' mysterious plans.", objectives = "Sage Edan at Camp Winterhoof wants you to compare the Rune Sample with the Broken Tablet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11367] = { id = 11367, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be a kind of keystone for the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. I will ask Chieftain Ashtotem to divert some of our men as we move north and dedicate them to eliminating the last of the runed giants. Without their giants, the Iron Dwarves cannot stand against us.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", completion = "You've done well in felling Megalith, but I wonder about his final words.\n\nYou're sure he said the Stoneforge?\n\nIt is not a name our people know, but it sounds like it might be a creation of the \"titans\" the ousiders speak of. The Iron Dwarves have ever been a cunning and dangerous foe, {name}. We must watch these giants and find this Stoneforge before they can carry out their plans.", objectives = "Defeat Megalith and return to Sage Edan at Camp Winterhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11368] = { id = 11368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Heart of Quagmirran", description = "I have an unusual request. A certain wealthy individual that I am in contact with off-world is interested in a macabre piece.\n\nSpecifically, she wants the heart of Quagmirran.\n\nI hear that the beast has three, but one will suffice for our purposes. As I understand it, you can find Quagmirran resting within a deep pool of water at the Slave Pens.", progress = "I trust that you know of a way to preserve the heart in transit?", completion = "Now that I think of it, it's a pity I didn't ask you to return with the other two hearts as well. Perhaps next time. In any case, you've earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to obtain The Heart of Quagmirran. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11369] = { id = 11369, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: A Black Stalker Egg", description = "There is only ever one great mother of the marsh walkers in Zangarmarsh. She is always known as the Black Stalker, and she hatches from one of the eggs left behind when her mother dies.\n\nI have a buyer who is interested in one of those eggs. He mentioned something about adding her as a zoo attraction.\n\nIf you are interested in the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.", progress = "We're speaking again because you have the egg? Outstanding, let me see it!", completion = "Is it not amazing to feel the life pulsing within the egg? I must hurry to deliver it to the purchaser. We wouldn't want it hatching here now would we?\n\nYour payment is ready.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem wants you to obtain a Black Stalker Egg. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11370] = { id = 11370, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Warlord's Treatise", description = "While it is known that Warlord Kalithresh of the naga is a great warrior in his own right, there are fewer who know that he has codified all of his knowledge.\n\nOne of my customers is aware of it though, and is keenly interested in obtaining his treatise.\n\nI ask that you travel to the Steamvault in Coilfang Reservoir and obtain this book for me.", progress = "My customer grows restless. I believe he wishes to plumb the depths of the warlord's tactical thinking to help with one of his ongoing conflicts.", completion = "Indeed, I fear my customer will not have time to peruse the entirety of this book. Nevertheless, that is not our concern.  Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to acquire The Warlord's Treatise. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11371] = { id = 11371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Coilfang Myrmidons", description = "Mah'duun hears and obeys, and I now ask you to be my instrument.\n\nIt has been related to me that the myrmidons of the coilfang tribe must be destroyed. Seek them out within the humid confines of the Steamvault underneath Coilfang Reservoir.\n\nI will accept nothing less than their utter annihilation.", completion = "I trust that it was a fight worthy of your time? Certainly this bounty will be.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", objectives = "Nether-Stalker Mah'duun has asked you to slay 14 Coilfang Myrmidons. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11372] = { id = 11372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Headfeathers of Ikiss", description = "I've recently been approached by a tauren whose husband is about to be elevated to chieftain. She wishes to make a special addition to his headdress.\n\nSpecifically, she wants to obtain the headfeathers from the dastardly Talon King Ikiss.\n\nIf you are interested in collecting my reward, travel to Auchindoun's Sethekk Halls and find him.", progress = "The time of the chieftain's ceremony grows near.", completion = "I am sure that these feathers will make a fine addition to the chieftain's headdress. You have earned your compensation, {class}.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to acquire The Headfeathers of Ikiss. Deliver them to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11373] = { id = 11373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Shaffar's Wondrous Pendant", description = "Today I have a personal request of you, yet the reward will certainly match the danger.\n\nMy family has a 'history', shall we say, with Nexus-Prince Shaffar and his followers. If the amulet he wears were to fall into my hands then surely that would mean that he had been dealt with.\n\nIf the bounty I am offering is of interest to you then journey to his lair within Auchindoun's Mana-Tombs.", progress = "Not many know that the source of Shaffar's magic rests solely within his amulet. Without it he is powerless.\n\nThen again, if you have it that must mean that he is dead.", completion = "<You sense a deep level of satisfaction from the wind trader.>\n\nGood, I am glad to hear of his demise. And perhaps I will be able to unlock the secrets of his amulet for myself. If not, then I will sell it for a handsome price.\n\nI trust that this reward is sufficient.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem wants you to obtain Shaffar's Wondrous Amulet. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11374] = { id = 11374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Exarch's Soul Gem", description = "Within Auchindoun's Auchenai Crypts many unsavory experiments are undertaken in the pursuit of a greater understanding of the necromantic arts. Many are the spirits that are tortured or destroyed therein.\n\nI have a customer who is interested in the liberation of one of those spirits. I have been informed that this spirit is contained within a soul gem held by none other than Exarch Maladaar himself.\n\nSeek him out within the crypts with all due haste and return to me with the gem.", progress = "Can you imagine being trapped within a gem for all eternity?", completion = "You're quite the hero, {name}. I am certain that my customer will find a way to free the spirit of their loved one from within the gem. For a job well done, your payment awaits.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to recover The Exarch's Soul Gem. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11375] = { id = 11375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Murmur's Whisper", description = "When I'm done speaking, you may not want to take this commission.\n\nI have an eccentric client who specializes in the study of dead realities. It is rumored that the being known as Murmur destroyed the last world from which he was summoned. The professor is interested in examining his 'whisper' as he called it to understand how it is that Murmur accomplished such a feat.\n\nWill you journey to the Shadow Labyrinth within Auchindoun and retrieve it for me?", progress = "I'm not even certain what form a whisper is supposed to take in the physical world, but the professor assures me that you'll know it when you see it.\n\nPerhaps it is something akin to the being's voice box?", completion = "I was worried that you might not return. I trust that you didn't go deaf from fighting Murmur?\n\nHere is your reward. The professor will be pleased no doubt, though I worry what he ultimately wishes to do with this thing.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to obtain Murmur's Whisper. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11376] = { id = 11376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Malicious Instructors", description = "Mah'duun has heard it said that none are as cruel as the six-armed demonesses inside the Shadow Labyrinth.\n\nGo to Auchindoun, seek them out, kill them all.\n\nIf you cannot accomplish so simple a task, we do not have anything further to say to one another.", completion = "I am satisfied. He who speaks through the nether shall be as well. Mah'duun has your bounty prepared.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'deen.", objectives = "Nether-Stalker Mah'duun wants you to kill 3 Malicious Instructors. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11377] = { id = 11377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge is Tasty", description = "I'm providing the catering for some unusual party guests tonight.  One of these fellows was flying around in Skettis and got knocked to the ground by a monstrous kaliri--his leg was broken badly.\n\nThey've requested something special for his get well party: Kaliri Stew.\n\nI can loan you my cooking pot so you can whip up a batch of stew for me.  The recipe itself is simple, but you'll need to get a giant kaliri wing and some cooked warp burgers.", progress = "Do I smell something tasty?", completion = "Oh, I do smell something tasty!  I hope you gave that bird quite a good beating.\n\nPlease, help yourself to some of my extra stock.  I'm sure someone of your talent could put it to good use.", objectives = "The Rokk in Lower City has asked you to cook up some Kaliri Stew using his cooking pot. Return to him when it's done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11378] = { id = 11378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Epoch Hunter's Head", description = "The tastes of my customers range from the mundane to the exotic. And sometimes they want to do very mundane things with the exotic objects they seek.\n\nSuch is the case with my latest request. My client, who shall remain nameless, wishes to obtain the head of the Epoch Hunter to mount on his wall.\n\n{class}, will you find a way to travel back in time to Old Hillsbrad and procure said head for my trophy-hunting patron?", progress = "The head of the Epoch Hunter... how does one come to the decision that they want it mounted on their wall?\n\nAnd even then, to not hunt the beast yourself, what does one say to their friends when asked how the fight went?\n\nHe'll lie, I suppose.", completion = "I see you are returned to the present time intact.\n\n<The wind trader looks around.>\n\nIt doesn't appear that anything has changed. But then again, how would I know?\n\nThat's a nice cut; my customer will be pleased. Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to obtain the Epoch Hunter's Head. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11379] = { id = 11379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Hot Stew", description = "I'm trying to invent something with some real zing.  But to be honest, I'm more of an idea goblin these days.  I've lost my sense of adventure.\n\nBut you... remind me of my younger days; ready to take on the world with a sword in one hand and a skillet in the other.\n\nI want you to take my beloved cooking pot and head out to Blade's Edge.  Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil it over an abyssal's corpse, the only thing hot enough to do the trick.", progress = "Any luck with my little experiment?", completion = "Now look at that...\n\n<The Rokk takes a sip of the concoction and his face twists into a bizarre mask of pain and delight.>\n\nSweet A'dal that's good!  A cook with your potential shouldn't be without his proper materials.  Take some of my extra stock and make me proud.", objectives = "The Rokk in Lower City has asked you to cook up some Demon Broiled Surprise using his cooking pot, two Mok'Nathal Shortribs and a Crunchy Serpent. Return to him when it's done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11380] = { id = 11380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manalicious", description = "Wouldn't you know it, I think my foodstuffs are up to date and someone comes along and requests the unusual: Mana Berry Delight.\n\nUnfortunately, mana berries are only found in the eco-domes of Netherstorm.  Just don't bother looking around Stormspire--it's picked clean.\n\nI could only trust someone trained in the culinary arts to pick the best berries, so don't let me down!", progress = "Any luck, friend?", completion = "Those are the juiciest mana berries I've ever seen.  I think I'm getting smarter just by looking at them.\n\nSince I no longer need most of my meat and fish stock, why don't you take some?  I'm certain you could make something delicious.", objectives = "The Rokk in Lower City has asked you collect 15 Mana Berries from the Eco-Domes in Netherstorm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11381] = { id = 11381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soup for the Soul", description = "Death is in the air.  I've never had so many orders for my famous soup--it lifts your spirits and soothes the soul.\n\nAnd I know a fellow cook when I see one!  Would you like to help me out and get a cut of the profits?\n\nHere, take my cooking pot, gather some clefthoof meat and I'll let you in on a little secret.  What makes my soup so good for the soul?  It's not chicken--I cook it at the Ancestral Grounds in Nagrand to soak up all that spiritual stuff there.", progress = "What smells so good?", completion = "That is a fine batch of spiritual soup if I ever did smell one.  Just a pinch of pepper and it's done.\n\nAs promised, here's your cut.  And because you did such a fine job, I'm going to throw in some of my extra stock.", objectives = "The Rokk in Lower City has asked you to cook up some Spiritual Soup using his cooking pot. Return to him when it's done.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11382] = { id = 11382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Aeonus's Hourglass", description = "I swear that some of my customers are crazy. There are possessions that you go after, and there are ones that you dare not even think of!\n\nMy current client is clearly over-the-top insane. He covets the hourglass that Aeonus holds.\n\nYes, you heard right, Aeonus of the Infinite Dragonflight!\n\nWho am I to argue since he's paying a king's ransom? So, ready to go to the Caverns of Time and travel to the Black Morass to retrieve it for me?", progress = "If I were you, I would be very careful with time-travel. You wouldn't want to accidentally do something, like kill one of your ancestors, and then accidentally erase yourself from the present!", completion = "Odd that the sands in that thing are still falling upward. I think I will have it delivered to its new owner with all due haste.\n\nI thank you for a job well done, {class}. You have certainly earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to acquire Aeonus's Hourglass. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11383] = { id = 11383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Rift Lords", description = "Mah'duun knows where you must go. Mah'duun knows that you must kill rift lords. But, Mah'duun does not know exactly when.\n\nI know that does not make sense, but the voice on the winds was not more specific.\n\nTravel to the Black Morass through the Caverns of Time and the way shall be made clear.", completion = "You found your way back in time, and then back again. You must be a great {class}, {race}. The bounty is earned.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", objectives = "Nether-Stalker Mah'duun wants you to kill 4 Rift Lords. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11384] = { id = 11384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: A Warp Splinter Clipping", description = "Not long ago, I was approached by a kaldorei druidess with a touching request. And plenty of gold, of course!\n\nIt would appear that the forces of Darnassus wish to restore an ancient of the arcane known as Warp Splinter. The giant tree has been confused or corrupted, I'm not certain, but you'll find it inside of the Botanica at Tempest Keep.\n\nShe said that all they would need to regrow him was a small clipping.", progress = "Did you lose your way to the Botanica? You can't miss it... it's at Tempest Keep off of the eastern edge of the Netherstorm.", completion = "Aw, you did get it! It's so tiny. And yet, when the druids are done with it -- a process I am told will take a very long time -- Warp Splinter will be regrown anew.\n\nAnd here is your reward as promised.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to obtain a Warp Splinter Clipping. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11385] = { id = 11385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Sunseeker Channelers", description = "It has been whispered to Mah'duun that the channelers of the military unit known as the Sunseekers must be killed today.\n\nThey are to be found within the Botanica at Tempest Keep.\n\nYou want the bounty, you kill the channelers.", completion = "And now they are dead, channeling no longer. He who whispers upon the nether is satisfied and you have secured the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", objectives = "Nether-Stalker Mah'duun wants you to kill 6 Sunseeker Channelers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11386] = { id = 11386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Pathaleon's Projector", description = "I always assumed that Pathaleon the Calculator used magic to project his image across Outland. Apparently I was wrong.\n\nMy latest customer tells me that the blood elf uses a mechanical device for his communication with the leaders of Prince Kael'thas's special projects. As I understand it, he acquired it from the Zaxxis rebels in the Netherstorm.\n\nMy client wishes to obtain the projector. Why don't you pay Pathaleon a visit? He can be found within the Mechanar at Tempest Keep.", progress = "It's not that projector technology is something special in and of itself, but the range of this particular model is a true breakthrough!", completion = "I'm tempted to keep it for myself and return my client's money. It could certainly expand the reach of my business.\n\n<The wind trader sighs.>\n\nHowever, I have a reputation to uphold.\n\nSpeaking of my reputation, thank you for helping me to maintain it. Here is your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to acquire Pathaleon's Projector. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11387] = { id = 11387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Tempest-Forge Destroyers", description = "There are mechanical constructs within the Mechanar which Mah'duun has been told must be dismantled.\n\nGo to Tempest Keep, find the tempest-forge destroyers and destroy them.\n\nThen you may return to collect the bounty.", completion = "Mah'duun enjoys fighting constructs; they are less messy than organic beings.\n\nThe bounty is yours.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", objectives = "Nether-Stalker Mah'duun wants you to destroy 5 Tempest-Forge Destroyers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11388] = { id = 11388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Scroll of Skyriss", description = "Today's client seeks something truly unique.\n\nIt is said that Harbinger Skyriss is a servant of the Old Gods. It is also said that he carries a large scroll that contains their instructions for his domination of life in the universe on their behalf.\n\nMy current buyer wishes to get <his/her> hands on that scroll, nevermind that <he/she> won't be able to read the language upon it.\n\nTravel to Tempest Keep's Arcatraz and get it for me, will you, {class}?", progress = "It must be a very dangerous thing to do to meddle directly in the affairs of the Old Gods.\n\nBetter you than me!", completion = "I dare not touch the scroll lest I too risk the notice of the Old Gods. I will have one of my assistants handle its delivery.\n\nYou have more than earned your reward, {class}, and I wish you all the luck in the known worlds.\n\nCome back tomorrow and I will have another request for you to fulfill.", objectives = "Wind Trader Zhareem has asked you to obtain The Scroll of Skyriss. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11389] = { id = 11389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Arcatraz Sentinels", description = "The sentinels within the Arcatraz have gone haywire. The prisoners run rampant and the guards attack those that would help.\n\nMah'duun hears the speaker on the nether winds. The speaker says to destroy the sentinels.\n\nAccomplish this and today's bounty is yours.", completion = "With the sentinels destroyed, perhaps the naaru will ask the Consortium to replace them? Mah'duun does not know and does not care.\n\nYou have earned the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", objectives = "Nether-Stalker Mah'duun wants you to dismantle 5 Arcatraz Sentinels. Return to him in Shattrath's Lower City once that has been accomplished in order to collect the bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11390] = { id = 11390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I've Got a Flying Machine!", description = "Well, what are you waiting for, there's work to be done!\n\nHere's the keys to our flying machine. Grab three sacks of relics and haul them up to the crane platforms on the north and south sides of Steel Gate.  I'll mark them for you.\n\nHurry up! We haven't got all day!", completion = "Good job, though I think ye might be wanting a refresher course in basic piloting.\n\nWell, no matter, one warm body's as good as another. Here's yer haul for the day.", objectives = "The Steel Gate Chief Archaeologist wants you to transport 3 Sacks of Relics from the bottom of the site and take them to the platform on the north or south side of Steel Gate.\n\nUse the grappling hook on the flying machine to do this.\n\nReport back to him after you've done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11391] = { id = 11391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steel Gate Patrol", description = "Eh? Yer back for another day's work?\n\nWell, alright, here's the keys. We don't need any haulin' today, so just keep an eye out for anything suspicious, okay?\n\nI've hooked her up with some rockets and a machine gun - just in case.", completion = "Nice shooting, ace.\n\nHere's your wages. Come back tomorrow for another round, ya hear?", objectives = "You're Steel Gate's ace pilot now, so the Steel Gate Chief Archaeologist wants you to keep patrol around the dig site and fight off anything that attacks.\n\nReport back to him when you're done with your patrol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11392] = { id = 11392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine.", objectives = "Take a Dreary Candle to the Loosely Turned Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11393] = { id = 11393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where is Explorer Jaren?", description = "{name}, my betrothed, Jaren, went west with a small group of explorers to check into rumors of artifacts on the Chillmere Coast. But there are murloc down there, and I fear the worst has befallen them.\n\nSurely you have time to see if they're alright? There's a way down to the beach just to the southwest, though watch out for the worgs and other things lurking in the woods.", completion = "<The explorer beams a smile as you tell him who sent you. He continues in hushed tones.>\n\nIrena was concerned about me?  She gets that from her father you know.", objectives = "Overseer Irena Stonemantle has asked you to locate her fiance, Explorer Jaren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11394] = { id = 11394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And You Thought Murlocs Smelled Bad!", description = "Originally I came down here to investigate some rumors about artifacts to be dug up. I knew that there were murlocs along the coast here, but I never in a million years thought I'd see this.\n\n<The explorer pokes his head out to look around the tree.>\n\nThe Scourge are out there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, I think it's our duty to do something about this. Think you could take out a good chunk of those Scourge?", completion = "<Jaren seems very excited about your success, but motions you to keep your conversation to a whisper.>\n\nGreat job, {name}! That's a lot of Scourge goo all over your stuff though. You might want to think about a quick dip in the strait. It's cold, but it'll get you cleaned up right quick.", objectives = "Explorer Jaren has asked you to kill 15 Scourge of any type along the Chillmere Coast. Return to him once you have done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11395] = { id = 11395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Explorer Jaren would like to have a look at this.", progress = "What an odd-looking device you have there, {class}. Let me have a closer look at it.", completion = "I know what this is! {name}, it's a controlling device for those scourging crystals!\n\nI bet anything that it can be used to shut down their force fields. Hmmm.", objectives = "Deliver the Scourge Device to Explorer Jaren on the Chillmere Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11396] = { id = 11396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nWhat do you say, {name}? You up for it? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nIt's the least we can do to keep the Scourge from making more of their own kind.", completion = "Nice!\n\n<Jaren looks around quickly to make sure that nothing noticed his outburst.>\n\nAlright, you certainly earned your pick of one of these things I found while I was down here.\n\nAnd, {name}, if you happen to find yourself back at Steel Gate, give Irena my love and let her know that I'm okay.", objectives = "Explorer Jaren on the Chillmere Coast has asked you to destroy 3 Scourging Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11397] = { id = 11397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And You Thought Murlocs Smelled Bad!", description = "I came here to investigate a rumor about a Scourge presence nearby. I expected murlocs along the coast down below, but I never thought I'd see this!\n\nThe Scourge are down there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, we will not suffer them to create more of their kind, especially not from murlocs! There is a ramp down to the beach just northwest of the camp. See to it that you deal with the Scourge in a timely fashion!", completion = "<Anastasia ponders your success for a moment.>\n\nA satisfactory job to be certain, yet somehow I sense that there's something else we should be doing to stop the efforts of the Scourge on that beach.", objectives = "Apothecary Anastasia has asked you to destroy 15 Scourge of any type along the Chillmere Coast. Return to her at the Apothecary Camp once you have done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11398] = { id = 11398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Apothecary Anastasia would like to have a look at this.", progress = "What's that you have there, {class}? Let me have a closer look at it!", completion = "I can tell you what this is, {name}. It's a controlling device for those scourging crystals down there!\n\nI bet anything that it can be used to shut down their force fields. Hmmm.", objectives = "Deliver the Scourge Device to Apothecary Anastasia at the Apothecary Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11399] = { id = 11399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nBrave enough to hazard another trip down there, {name}? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nHow can you refuse if it means less Scourge, especially ones made from murlocs?", completion = "<Anastasia turns and smiles at her succubus.>\n\nVery well, {name}, I concede that you have certainly earned a choice of one of these.", objectives = "Apothecary Anastasia at the Apothecary Camp has asked you to destroy 3 Scourging Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11400] = { id = 11400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Riding Rams", description = "If you show this hand stamp to Pol Amberstill, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", objectives = "Bring the \"Honorary Brewer\" Hand Stamp to Pol Amberstill near the entrance to the Brewfest Grounds in Dun Morogh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11401] = { id = 11401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", objectives = "Take a Dreary Candle to the Loosely Turned Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11402] = { id = 11402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clayton's Quest: Extreme!!", description = "Clayton wants you to find and slay twenty Evil Squirrels.", objectives = "Seriously, go slay those Evil Squirrels!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11403] = { id = 11403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.", progress = "{name}, it is good to see you again.  I'm sure the children enjoy tales of your heroism.", completion = "What?  This holy tome once belonged to an infamous paladin of the Alliance.  Was he the Headless Horseman?  Does this mean that the Horseman is defeated?\n\nThis is a glorious day, {name}!  Your legend will shine bright, and may it last for twice the years of the Horseman's reign of fear.", objectives = "Take the Tome of Thomas Thomson to a Masked Orphan Matron in Durotar, Brill or Falconwing Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11404] = { id = 11404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", objectives = "Take a Dreary Candle to the Loosely Turned Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11405] = { id = 11405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", objectives = "Take a Dreary Candle to the Loosely Turned Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11406] = { id = 11406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Everything Must Be Ready", description = "When the expeditionary force moves north, Captain Adams expects everything to be ready at Fort Wildervar. The scouts and craftsmen there have been tasked with preparing the gear and rations for our men for the climb into the hills.\n\nThe captain's famous for his temper, so I want to send someone ahead to check on the preparations. Fort Wildervar is far to the northeast, beyond Skorn, up in the snow-covered areas near the border with Grizzly Hills. Find Gil Grisert there and make sure he is prepared.", completion = "So the quartermaster sent you?\n\n<Gil seems relieved.>\n\nTo be honest, we're running a bit behind here and we're going to need some help making our goals.\n\n<Gil shudders.>\n\nNone of the men want to brave the wrath of Captain Adams.", objectives = "Speak with Gil Grisert at Fort Wildervar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11407] = { id = 11407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for Drohn's Distillery!", description = "So, do you want to help bring strength and honor to Brewfest?  We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nWe'll lend you a racing ram for 4 minutes.\n\nBe careful though, the cheap goblins didn't put any apple crates along the way.", progress = "Have you finished spreading the word about Brewfest?", completion = "You kept your word and let people know about our brewmasters.  Thank you. We promised you these tokens, and gladly give them to you.  I imagine the trolls are a bit more stingy with handing over their tokens...\n\nCome back another day to help us spread the word about Brewfest.", objectives = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11408] = { id = 11408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bark for T'chali's Voodoo Brewery!", description = "We need to spread the word about the trolls at Brewfest.  Ya need to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nBut I'll make it easy for ya, I'll lend you a racing ram for 4 minutes.\n\nBe careful though, the goblins didn't put any apple crates along the way.  They are cheap like that.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the amazing troll brew?", completion = "Ya did it!  We gotta get ready for the flood of customers that are sure to come our way!  Thanks!\n\nOh, that's right, and we promised you a reward.  Can't forget about that...\n\nFeel free to stop by again another day to help us spread the word some more.", objectives = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11409] = { id = 11409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams? The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal: I'll lend you the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", progress = "Have you got a handle on riding racing rams?", completion = "Hey, that wasn't too bad... are you sure you're not a dwarf?\n\nSo there's plenty more racing to be had and it's not just from me.  All over the Brewfest grounds you'll find people in need of a decent ram racer.  So go and make yourself useful.\n\nOh and don't forget, these rams were legally obtained.  I just want to make sure we're clear.", objectives = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11410] = { id = 11410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The One That Got Away", description = "The barbfish you brought should work well as bait for most fish, but I fear it'll attract a monster!\n\nWhen I first arrived, I put some of Nat Pagle's favorite bait on my hook and cast it into the water. A huge monster latched on, with giant teeth and icicles hanging from its fins!\n\nWould've pulled me into those icy waters if I hadn't cut the line! I can't use the new bait until ol' Frostfin's been dealt with. Use this bait near the sunken boat in the middle of the lake. He won't be able to resist!", completion = "At last, we can finally fish in peace! 'Course, by the time we catch anything, the expedition'll arrive and claim it all for themselves.\n\nYou have our thanks, {name}. Don't be a stranger 'round here.", objectives = "Christopher Sloan at Fort Wildervar wants you to defeat Frostfin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11411] = { id = 11411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Camp Winterhoof", description = "In my travels as a courier, I've seen a number of strange denizens of the Howling Fjord, but one group stands out. From a distance, they look like tauren, but upon closer inspection, they're quite different -- sturdier and shaggier.\n\nI found one of their settlements far to the north, beyond Halgrind, Skorn, and the northern forests. Camp Winterhoof, it's called, and it sits in the foothills of Gjalerhorn near the border with Grizzly Hills. Make contact with them, and see if they might be of use to us.", completion = "<The chieftain listens as you introduce yourself.>\n\nI am Chieftain Ashtotem, and my people are the taunka, and I will speak truly, outsider. Among my people, trust is earned, not given. You have my leave to walk among them and offer your assistance. Time grows short and some of them may welcome even an outsider's help with their preparations.", objectives = "Speak to Chieftain Ashtotem at Camp Winterhoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11412] = { id = 11412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "There and Back Again", description = "Am I glad you're here. We are in big trouble! There's been a brew accident on the road to Bladefist Bay, and kegs are no longer being transported. You gotta get us that brew!\n\nI'll put you on one of my racing rams and you follow the road to Bladefist Bay.\n\nOnce you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant. For now, all we want are 3 kegs. Do a good job and maybe we'll have another job for you.", progress = "Did you see the mess that goblin made?  I hope you didn't do too much reckless off-roading.", completion = "Thanks for your help!  As long as Brewfest is going, the Dark Iron dwarves are attacking and our supplier is stuck in that canyon, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nHere are the tokens we promised you.  Have fun!", objectives = "Get a keg from the goblin stranded on the road to Bladefist Bay and return it to Ram Master Ray's assistant. If you lose your ram, ask Ram Master Ray for another.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11413] = { id = 11413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Did Someone Say \"Souvenir?\"", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11414] = { id = 11414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Betrayers", description = "Watcher Moonleaf is from my dreams! If you are her friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha worg. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place called Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", progress = "<A low growl rises from Ulfang's throat.>\n\nBjomolf and Varg are not dead!", completion = "The smell of their blood upon your muzzle pleases me. Brothers should not turn on each other.", objectives = "Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11415] = { id = 11415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Betrayers", description = "Mistwalker is from my dreams! If you are his friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place the two-legs call Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", progress = "<A low growl rises from Ulfang's throat.>\n\nBjomolf and Varg are not dead!", completion = "The smell of their blood upon your muzzle pleases me. Brothers should not turn on each other.", objectives = "Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11416] = { id = 11416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", progress = "You have the eyes of the eagle?", completion = "<Ulfang howls loudly at your defeat of his great eagle enemy.>\n\nThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.\n\nLet us not waste the sacrifice that she has made for us. Here, eat them!", objectives = "Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11417] = { id = 11417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", progress = "You have the eyes of the eagle?", completion = "<Ulfang howls loudly at your defeat of his great eagle enemy.>\n\nThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.\n\nLet us not waste the sacrifice that she has made for us. Here, eat them!", objectives = "Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11418] = { id = 11418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Call Him Steelfeather", description = "We see one brave hippogryph circling over the fort, then swooping down and taking prey. Jethan over there has taken a couple of shots at the creature, but his arrows bounced right off!\n\nWe've taken to calling this remarkable creature Steelfeather, but we can't see why he prefers the area around Fort Wildervar. Most hippogryphs are wary of people.\n\nResearcher Aderan has helped us fashion a charm from one of the creature's feathers. He claims it will allow the user to see through Steelfeather's eyes.", progress = "Did Aderan's charm work?", completion = "You saw a nest, with hatchlings? Hmm... so our \"he\" is actually a \"she,\" eh?\n\nI guess that settles it. I suppose I wouldn't want to move a nest full of hatchlings just because of a new neighbor, either.\n\n<Gil favors Trapper Jethan with a mock glare.>\n\nI'm sure we'd get along just fine if ol' Jethan would stop trying to make a trophy of her.", objectives = "Locate Steelfeather circling Fort Wildervar and use the Feathered Charm to discover his secret. Report your findings to Gil Grisert.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11419] = { id = 11419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest Riding Rams", description = "If you show this hand stamp to Driz Tumblequick, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", objectives = "Bring the \"Honorary Brewer\" Hand Stamp to Driz Tumblequick near the entrance to the Brewfest Grounds in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11420] = { id = 11420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to Payback", description = "Two weeks ago our chief engineer got his hands on a vrykul harpoon gun - the same type of gun that the vrykul use to take down our ships. By studying that gun he managed to put together a comprehensive operation manual.\n\nUnfortunately he was abducted and taken north of here to Wyrmskull Village. We eventually did find him, but near death and without the manual. His dying words indicated that the manual was lost in the Utgarde Catacombs, located at the northwest end of Wyrmskull. Get me that manual!", progress = "Did you find the manual?", completion = "<Zorek flips through the manual.>\n\nHrm, interesting...\n\nAccording to the manual, the vrykul have a special tool that allows them to control the harpoon guns with deadly accuracy. It looks a bit like the wheel of one of our ships. Furthermore, it's portable and seems to plug into the harpoon guns like a key. We need to get our hands on one of those!", objectives = "Guard Captain Zorek at Valgarde in Howling Fjord wants you to recover the Harpoon Operation Manual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11421] = { id = 11421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Goes to 11...", description = "We must strike while the vrykul forces are in disarray! Take the harpoon control mechanism to Nifflevar and locate the northernmost harpoon building on the bluff side of the village.\n\nOnce there, commandeer one of the vrykul harpoon guns that are stationed on the building's deck. Use the harpoon gun to rain hell upon Wyrmskull Village! Destroy the longhouse, dockhouse, storage facility and any defenders that the vrykul may send at you!\n\nDo this and Daggercap Bay will become a much safer port!", progress = "Is Wyrmskull up in flames?", completion = "Excellent work, {name}! You took out a good chunk of their dragon riders and really pissed off their leadership.\n\nAre you ready to head back to Valgarde and report the good news to Zorek? If so, I've got a crazy idea!", objectives = "Lieutenant Icehammer in the Howling Fjord wants you to destroy the Dragonflayer Longhouse, Dragonflayer Dockhouse, Dragonflayer Storage Facility and 8 Dragonflayer Defenders.\n\nReturn the Harpoon Control Mechanism to him once the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11422] = { id = 11422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trident of the Son", description = "<From the scratches he makes in the rock, you see several symbols: a trident, a mur'ghoul, the sun, a wrecked ship, and a rough stick-figure of yourself.>\n\n<Puzzling out what the murloc is conveying takes a while. Obviously he wants you to get a trident from the Chillmere Coast, but the image of the sun is puzzling. That is until you realize he means his son.>\n\n<His son was changed into a mur'ghoul! He wants you to find him to the south near the wrecked ship and return with his trident.>", progress = "<One of Old Icefin's dead fish-like eyes studies you, clearly looking for signs of his son's trident.>", completion = "<Reaching out to take his son's trident from you, Old Icefin's hand shakes a little. Could it be that the aged murloc is grieving?>\n\n<Is that just extra moisture pooling at the base of his eye?>", objectives = "Old Icefin wants you to obtain Rotgill's Trident. Return it to him on the small island on the Chillmere Coast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11423] = { id = 11423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Enemy's Legacy", description = "As our armies march through Northrend, our enemies will not suffer mere defeat.  Their houses will burn, their corpses will be devoured by our plagues, all trace of their existence will be lost.\n\nThis worries me as a seeker of knowledge.  The eastern town of Nifflevar will soon be razed by our forces in Vengeance Landing.  The vrykul bard, Helgus, lived there and wrote three sagas: the Saga of the Twins, the Saga of the Winter Curse and the Saga of the Val'kyr.  Obtain them before Nifflevar is destroyed.", progress = "The scrolls, {name}?  Did you obtain them?", completion = "This is of tremendous value, {name}.  I must renew my efforts in salvaging and translating vrykul texts.\n\nDon't get me wrong.  Our enemies need to be destroyed... their ancient knowledge doesn't.", objectives = "Go into Nifflevar, north of Ghostblade Post and look for the Saga of the Winter Curse, the Saga of the Val'kyr and the Saga of the Twins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11424] = { id = 11424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shield Hill", description = "My work should be extremely easy in a time of war.  There ought to be usable body parts everywhere.\n\nIt's not that simple, though.  With these eggheads making all sorts of killer plagues and sending them to enemy towns, most of the material gets contaminated.\n\nThere is a place, though, where usable samples exist.  Shield Hill, south of here, is an ancient vrykul burial ground where the dead walk but are not afflicted with any plague - ours or the Lich King's.  Get me some bones, I'll pay ya well.", progress = "Got my bones then?", completion = "Hmmmmph... these will do for now.  There seems to be some oddness to them.\n\nI tell ya - I've handled body parts for years now and never have I had such a weird feeling in my stomach.  Anyway, a deal is a deal.  Here's your payment.", objectives = "\"Hacksaw\" Jenny wants you to bring her 5 Ancient Vrykul Bones from the reanimated Vrykul in Shield Hill, south of New Agamand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11426] = { id = 11426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locating the Mechanism", description = "Don't worry, {name}; this is all going to lead to something big! HUGE! You're just going to have to trust me for now and do as I ask of you.\n\nWe need to get the mechanism mentioned in the manual for the next step of the plan. I have a strong suspicion that you'll find one on one of those vrykul that operate the harpoon guns in Wyrmskull Village. You'll find them on the east side of the village, on the docks by the longhouses.", progress = "Did you locate the mechanism?", completion = "Outstanding! Those overgrown apes will soon know what it means to mess with the Alliance!", objectives = "Guard Captain Zorek at Valgarde in Howling Fjord wants you to bring him a Harpoon Control Mechanism.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11427] = { id = 11427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Lieutenant Icehammer...", description = "Do you see those vrykul buildings on the bluffs to the northeast? The vrykul call that place Nifflevar. It's where most of their harpoon attacks on our frigates originate.\n\nWell guess what? The time for payback has come, {name}. I need you to take this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out in a vrykul building northwest of Nifflevar.\n\nWhen you're ready I'll place you on the back of one of our gryphons and zip you right to him!", progress = "What is this? Do I look like a babysitter?", completion = "<Lieutenant Icehammer takes the harpoon control mechanism from you.>\n\nAh, you come bearing gifts!", objectives = "Guard Captain Zorek wants you to take the Harpoon Control Mechanism to Lieutenant Icehammer stationed outside of Nifflevar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11428] = { id = 11428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeper Witherleaf", description = "You have been a great friend and ally to us, {name}. There is one more thing I must ask of you.\n\nYou have seen the corruption of the Twisted Glade and the beasts that dwell there. The blacksouled keepers will continue raising these abominations from the waters and soil of our glade unless we act against them.\n\nThe most powerful of the blacksouled keepers is known as Keeper Witherleaf. Slay him, {name}, and open the way for the redemption of the glade as you once redeemed my sisters.", completion = "My heart broke when I learned the keepers had turned against us. Once, we considered them our brothers and our closest friends.\n\nI grieve for the brothers and sisters we have lost, but without your help, there would be no hope for our future. You will always be welcome among us, {name}.", objectives = "Lurielle at the Frozen Glade wants you to kill Keeper Witherleaf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11429] = { id = 11429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drop It then Rock It!", description = "I'm not about to put the fate of this mission into the hands of some untested scrub.\n\nNow, if you want to prove to me that you've got what it takes to carry out this mission, you'll need to do what I tell you.\n\nTake this battle standard and head over to Baleheim, directly north of here. Once you're at Baleheim, find the center of town and drop our flag. Fight off any vrykul dirt bags that attempt to take down our beloved flag and return to me once you've established Alliance dominance!", progress = "Still alive, I see. Clearly you're not trying hard enough.", completion = "For the Alliance! You're a strong one, {name}. Strong enough to crack some vrykul skull at Nifflevar.", objectives = "Lieutenant Icehammer in the Howling Fjord wants you to place the Alliance Banner in Baleheim and then defend the banner against attackers.\n\nReturn to Lieutenant Icehammer with the Alliance Banner should you survive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11430] = { id = 11430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpoon Master Yavus", description = "That was a fairly strong showing at Baleheim, {name}. Before you go off patting yourself on the back there's work to be done at Nifflevar.\n\nWe've located the vrykul responsible for the majority of the harpoon attacks on our frigates - goes by the name of Yavus. You'll find him in the main harpoon structure on the bluffs of Nifflevar, southeast of here.\n\nTrack him down and execute him for crimes against the Alliance!\n\nDo me proud, {name}!", progress = "Have you taken care of Yavus?", completion = "It'll take them a while to find a replacement for Yavus. Now is the perfect time to unleash Zorek's plan! While they're scurrying to regain control of Nifflevar, you're going to use their own harpoon guns against them!", objectives = "Lieutenant Icehammer in the Howling Fjord wants you to slay Harpoon Master Yavus at Nifflevar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11431] = { id = 11431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catch the Wild Wolpertinger!", description = "On Draenor, many creatures posed a tough hunt. However, I've never encountered a creature such as the wild wolpertinger of Azeroth!\n\nThese beasts are not to be found most of the year, but the sounds and smells of Brewfest seem to draw them out. If you look around, you still may not see them... which is where these goggles come in handy!\n\nProve to me you are a worthy hunter and bring me five of these wolpertingers alive. If you need some goggles, I have some to spare.", progress = "Do you have something for me or are you just looking for some Synthebrew Goggles?", completion = "What!  They really exist!   Now I feel bad for kicking that dwarf in the knee...\n\nI need a minute... and a drink...\n\n<He takes a drink from his stein.>\n\nI guess I could let you keep one... Proof that drunk dwarves (are there any other kind?) actually tell the truth.", objectives = "Snipehunter Goro has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. You must be wearing Synthebrew Goggles to see them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11432] = { id = 11432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleeping Giants", description = "I've overheard what you've had to say with Father Levariol. Allow me to suggest that he's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", completion = "You did what had to be done. Though some might consider it dishonorable to slay the helpless, in this case you would have been a fool to have done otherwise.\n\nAnd we certainly couldn't have just left them standing there to be ritually wakened, now could we?\n\nIt was a brave thing you did for all of us down in those catacombs, {name}.", objectives = "Mage-Lieutenant Malister has tasked you with slaying 5 Dormant Vrykul. Return to him at Westguard Keep when you have done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11433] = { id = 11433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleeping Giants", description = "I've overheard what you've had to say with Greatmother Ankha. With all due respect, she's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", completion = "You did what had to be done. The unwise might consider it dishonorable to slay the helpless while they awaken, but in this case you would have been a fool to have done otherwise.\n\nAnd we certainly couldn't have just left them standing there to be ritually wakened, now could we?\n\nIt was a brave thing you did for all of us down in those catacombs, {race}.", objectives = "Ahota Whitefrost has tasked you with slaying 5 Dormant Vrykul. Return to him at Camp Winterhoof when you have done so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11434] = { id = 11434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forgotten Treasure", description = "I've made my fortune by specializing in treasure that regular pirates don't appreciate: art, antiquities, collector's pieces.\n\nBlack Conrad's fleet sank south of here years ago.  All the gold and jewelry was picked clean by divers, but two ancient relics remain there.  One is a museum-quality Amani vase, the other is an eagle figurine.\n\nGo and retrieve them for me and I'll vouch for you with the other pirates.  I'll even throw in something to make your underwater adventure a bit more manageable.", progress = "Did you obtain my relics, {name}?  Nobody gets by in this life on good looks alone... not even me!", completion = "We're going to go places together, {name}.  With my good looks and your... can-do attitude, we're sure to make a killing.", objectives = "Handsome Terry at Scalawag Point wants you to bring him 1 Amani Vase and 1 Eagle Figurine from the shipwreck to the south.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11436] = { id = 11436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let's Go Surfing Now", description = "Navigating the steep bluffs of Howling Fjord can be nerve-racking! I've come up with a solution to ease that burden by utilizing vrykul technology and dwarven ingenuity. With just a few adjustments and some fine tuning I've created Icehammer's harpoon controller! Of course it hasn't been tested, but that's what you're here for!\n\nTake the controller to the big gun in Nifflevar and use it to launch yourself into Valgarde. Report your victory to Zorek. Oh yea, you can keep the controller.", progress = "<Zorek raises an eyebrow at you.>", completion = "You are insane, {name}! What kind of degenerate would actually launch themselves from a harpoon gun as a method of travel?\n\nBut I guess you need to be a little crazy to pull off what you did up there on the bluffs! Fantastic work! We've gotten word that the Dragonflayer leader, Ingvar, is furious! Maybe one day you'll be ready to stomp his face into the dirt - in the name of our beloved Alliance.", objectives = "Use the large Vrykul Harpoon Gun in Nifflevar to launch yourself into Valgarde. Report your victory over the Vrykul to Guard Captain Zorek.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11439] = { id = 11439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help?\n\nSouth of here, the mountaineers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", completion = "You're smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", objectives = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11440] = { id = 11440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Brigade Practice", description = "With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help?\n\nWest of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", objectives = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11441] = { id = 11441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest!", description = "Have you heard? It's time for Brewfest! You should speak to the Brewfest organizer at the grounds just outside of Ironforge--he'll give you a free beer to kick things off!", completion = "Ho ho! Come for your free beer?", objectives = "Speak to the Brewfest Organizer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11442] = { id = 11442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Brewfest!", completion = "Ho ho! Come for your free beer?" }
quests[11443] = { id = 11443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daggercap Divin'", description = "Hey... Uh... What's up? What are you doing down here?\n\nMe? Oh... Well, you see... I'm... Um... I'm trying to clean this place up! Orders from Keller himself! He says to me, \"Harry, I want you to put on a divin' bell and search the shipwrecks of Daggercap for OUR stuff...\"\n\nSay, maybe you could lend me a hand while you're down here. Throughout the bay here are all kinds of goodies, err, I mean supplies. Go out and bring me back whatever you find. Use this diving helm so you don't run out of air and die.", progress = "Did you find those supplies?", completion = "Wow! You sure are efficient. Yep, well, just give me those crates. I'll need to document them and take inventory and some other stuff that you haven't been trained to deal with or understand. Don't worry; I'll be sure to let Keller know what a great job you did down here! Yep. Yea, you can leave now. Skedaddle!", objectives = "Harold Lagras at the bottom of Daggercap Bay wants you to recover 10 Valgarde Supply Crates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11446] = { id = 11446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewfest!", description = "Have you heard? It's time for Brewfest! You should speak to the Brewfest organizer at the grounds just outside of Orgrimmar--he'll give you a free beer to kick things off!", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year.", objectives = "Speak to the Brewfest Organizer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11447] = { id = 11447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Brewfest!", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year." }
quests[11448] = { id = 11448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Explorers' League Outpost", description = "It's all a bunch of cryptic nonsense! Even with this cipher I can't make heads or tails of these tablets. Admittedly, cryptography is not my strong point.\n\nYou'll need to take the cipher and tablets to our cryptographer, Stanwad. Unfortunately, I haven't heard from Stanwad in two weeks. He took a team of twenty scientists to the dig sites on the southeastern bluffs of the fjord and hasn't been heard from since. The best I can do is have McGoyver over there give you a lift with his flying machine.", progress = "<Stanwad grumbles.>", completion = "<Stanwad takes the bundle from you and begins sorting the data.>\n\nWow. How many people did you say died to get this information?\n\n<Stanwad shakes his head.>\n\nYou'll be happy to know that what McSorf and his crew of bumbling imbeciles discovered is an ancient recipe for tundra stew. Did he not notice the icons of common vegetables and the pictograph of a humanoid mouth chompin' down on said veggies? You don't need a damned cipher to break this code!", objectives = "Deliver McSorf's Bundle to Stanwad at the Explorers' League Outpost in Howling Fjord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11449] = { id = 11449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The deathstalkers have set up a fire training area outside the town.  We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter.\n\nHead west past the graveyard, following the road. You'll find the training area there.", completion = "Well done, {name}.  Children, take a good look at this {class}.  Let him be a strong example to you.", objectives = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11450] = { id = 11450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Training", description = "The guards have set up a fire training area outside the town.  We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter.\n\nHead south through the gate to the crossroads. You'll find the training area there.", completion = "Well done, {name}.  Children, take a good look at this {class}.  Let him be a fine example for you to follow.", objectives = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Falconwing Square.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11451] = { id = 11451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alicia's Poem", description = "Hi, I wrote a poem for my friend Caylee.  She likes to hang out with the Aldor in Shattrath City.  You know, in Outland?\n\nCould you take my poem to her?  My mommy says I'm too young to go to Shattrath City!", progress = "Oh, is that a poem?", completion = "What a touching poem, thank you!", objectives = "You have been asked to deliver Alicia's Poem to Caylee Dak in Shattrath City in Outland.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11452] = { id = 11452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", completion = "I'm not sure that I like the sound of that one bit! The Lich King absconding with Ymiron can only mean trouble. Unfortunate that you weren't able to kill him along with his queen.\n\nStill, you've put a huge dent in their plans and bought us the valuable time that we need.\n\nAnd who knows, with the way you get around, you'll likely run into King Ymiron again. I'm sure that he won't fare so well the next time you meet.", objectives = "Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Westguard Keep and report your success to Captain Adams.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11453] = { id = 11453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", completion = "I'm not sure that I like the sound of that one bit! The Lich King absconding with Ymiron can only mean trouble. Unfortunate that you weren't able to kill him along with his queen.\n\nStill, you've put a huge dent in their plans and bought us the valuable time that we need.\n\nAnd who knows, with the way you get around, you'll likely run into King Ymiron again. I'm sure that he won't fare so well the next time you meet.", objectives = "Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Camp Winterhoof and report your success to Chieftain Ashtotem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11454] = { id = 11454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seek the Saboteurs", description = "This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.\n\nWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.", sourceObjective = "Find Coren Direbrew in the Grim Guzzler within Blackrock Depths.", sourceObjectiveStatus = "unverified-source-field" }
quests[11455] = { id = 11455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fragrance of Money", description = "Us pirates are known for many things, but hygiene isn't one of them.  Most pirate ships be carrying five or six times as many rats as people.\n\nIt's no wonder all the bears on this island caught the rabies soon after we moved in.  Long story short, the boss wants 'em all dead.\n\nIt just so happens I know a recipe for a bear musk fragrance popular among Stormwind nobles.  We kill the bears and sell the musk.  I see a fine business opportunity for us here.  What say ye?", progress = "Ye got the bear musk for me, matey?", completion = "Excellent work!  It might not be quite as daring as plundering the high seas, but I'd be a darned son of a deckswabber if I passed on this opportunity.", objectives = "Handsome Terry at Scalawag Point in Howling Fjord wants you to obtain 4 Bear Musk from the Rabid Brown Bears in the surrounding area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11456] = { id = 11456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding the Survivors", description = "We tuskarr rely mostly on our fish catch for sustenance.  In times of great need, however, we will on occasion hunt land animals.\n\nThe nearby village of Iskaal was recently attacked by pirates and the survivors just keep pouring in.\n\nOur catch has been modest this week, but there are many shoveltusk on the island and their meat is plentiful.\n\nAid my people by hunting these great beasts and obtaining their meat.", progress = "Have you obtained the meat we need?", completion = "I thank you, {name}.  My people are in a time of great need.", objectives = "Elder Atuik at Kamagua in Howling Fjord wants you to obtain 6 pieces of Island Shoveltusk Meat from Island Shoveltusk in the Isle of Spears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11457] = { id = 11457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arming Kamagua", description = "Issliruk, the spirit of war, is depicted as a silver eagle by my people.  Our stories tell of how Issliruk fought against a hundred worgs to save his young.\n\nIt is time for us, too, to fight against our foes to save our brethren.  We will need to craft new weapons.  The horns of the frostwing chimaera that make their home in the snowy parts of the island are sharp and are easily crafted into spear tips.  Bring me the best of these horns that you can find.", progress = "It's good to see you again, {race}.", completion = "You continue to prove your worth as an ally, {name}.  Your actions will not be forgotten.", objectives = "Elder Atuik wants you to obtain 3 Chimaera Horns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11458] = { id = 11458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge Iskaal", description = "The totem of Issliruk is ready, {name}, and for that I thank you.  We must cast our peaceful ways for the time being and strike at those who've attacked our land and our kin.\n\nThe pirate slavers that raided Iskaal have lost their minds and slaughtered all their captives.  Go to Iskaal, to the east of here and do what must must be done.  Take this horn and call on my brethren should you need assistance.", completion = "You are a formidable ally, {name}.  My people will forever be in your debt.", objectives = "Elder Atuik wants you to go to Iskaal and slay 8 Northsea Slavers. Use the Horn of Kamagua should you need assistance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11459] = { id = 11459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeh'gehn Sez", description = "Is like dis, mon.  Ye be wantin' me 'elp spotting some craven bag-o-wire been cardin' da crew?\n\nYe gotta bring me a croaker, matey.  Aft I an' I show ye who da blaggard be, mon.  Nah, nah, croaker show ye.  Ye'll ku fer yerself with yer own deadlights, yahso.\n\nBring us a carver yahso too, 'atsteppa.  Galang, bucko.", completion = "You didn't understand a thing Zeh'gehn said?  Well, of course not.\n\nLet's see then.", objectives = "Return to Handsome Terry to decipher what Zeh'gehn asked of you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11460] = { id = 11460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trust is Earned", description = "The first and most important factor in falconry is the bond between the falconer and <his/her> bird. Trust must be earned by the master!\n\n<Hidalgo points to the falcons in the cage at his feet.>\n\nIf you are to earn their trust you will first need to fill their bellies.\n\nThe fjord rock falcon, as these birds are known, primarily eat grubs. Throughout the fjord you will find loose rocks that serve as breeding grounds for these grubs. Find a grub and return here to feed the falcons in the cage.", progress = "This is an important exercise, {name}. If you are to become a falconer you must learn how to feed your bird.", completion = "Yes, {name}. I can see the bond of companionship forming. She has accepted you as master.", objectives = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to find a Fjord Grub and feed it to one of the falcons in the cage by his feet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11462] = { id = 11462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handsome Terry", description = "Your people paid me good money to infiltrate the Northsea Freebooters and get your foot in the door.\n\nI talked you up to a fellow in Scalawag Point called Handsome Terry.  I told him you come highly recommended.\n\nPut your disguise on and go see him.  Here comes someone to take you there.\n\nYou're going to have to prove yourself a bit before they introduce you to their higher ups.  But that's all up to you.  Remember, {name}, once you're inside you're on your own!", objectives = "Don the Pirate Disguise and speak to Handsome Terry inside Scalawag point.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11463] = { id = 11463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirates of the North Seas", description = "The past few weeks have seen an increase in pirate attacks against our supply ships.  We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates.\n\nThis group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef.  We don't know much about them, but we do know that Sylvanas wants their leader's head.\n\nYou come very highly recommended, {name}.  If you take on this task, we can keep our military focused against Arthas' forces.  Are you up to it?", sourceObjective = "Find Grezzix Spindlesnap on the northern end of Garvan's Reef off of the Southwestern coast of Howling Fjord.The past few weeks have seen an increase in pirate attacks against our supply ships. We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates.\n\nThis group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef. We don't know much about them, but we do know that Sylvanas wants their leader's head.\n\nYou come very highly recommended, {name}. If you take on this task, we can keep our military focused against Arthas' forces. Are you up to it?", sourceObjectiveStatus = "unverified-source-field" }
quests[11464] = { id = 11464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gambling Debt", description = "I heard you did a little work for Terry.  I was hoping someone reliable would show up around these parts.\n\nSee, pirates love to gamble.  They, however, do not love to pay their gambling debt.\n\nIf you're interested in collecting some coin on my behalf, I'd be willing to give you a cut.\n\nLet's start you out with an easy one.  \"Silvermoon\" Harry's a bit of an eccentric, keeps all sorts of expensive blood elf knickknacks inside his tent - yet when I see him he always pretends to be broke.  Get my gold.", progress = "You're back.  Did you get what's owed to me?", completion = "A job well done.  Here's your cut, {name}.  There's more where this came from.\n\nThere's no shortage of deadbeat pirates on this island.", objectives = "Taruk at Scalawag Point wants you to collect \"Silvermoon\" Harry's Debt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11465] = { id = 11465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ransacked Caravan", description = "I was leading a caravan here from Valgarde that was attacked by Dragonflayers. I was the only survivor of that ambush. Unfortunately, I couldn't make it back here with the cargo of fjord turkeys. This is the perfect opportunity for you to get your feet wet with your rock falcon.\n\n<Hidalgo hands you a cage.>\n\nTake this falcon cage and head west down the road leading out of this camp. Use the falcon to capture the loose turkeys and return here when you've gathered enough.\n\nRemember to feed the falcon!", progress = "Your falcon must be constantly fed or else it will eat the prey that you are sending it to kill.", completion = "Clever fiends. And patient too! We need to stop underestimating our enemy. Those vrykul are deadly hunters!\n\nRegardless, mission accomplished. Perhaps it is time for you to hunt something a bit more elusive than a fat turkey, eh?", objectives = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use the Trained Rock Falcon to recover 5 Fjord Turkeys.\n\nReturn to Hidalgo with the cage once you have completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11466] = { id = 11466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jack Likes His Drink", description = "Our next customer,  Jack Adams, won't be the pushover that Harry was.  He spends all day drinking with his friends, tough pirates all of them.  Let's not use force this time, could get ugly.\n\nSee if you can use his drinking habit to your advantage.  There's only so much alcohol someone can handle before passing out.\n\nMaybe one of the bar wenches will be of assistance.  Once he's out, see if you can slip your hand into his pocket and get what's mine.", progress = "Did you get what's mine, {name}?", completion = "I'm impressed, {name}.  And I'm not the type who's easily impressed.", objectives = "Taruk at Scalawag Point in Howling Fjord wants you to collect Jack Adams' Debt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
